 "Applying is a roll: what you are good at and the traits the job looks for are your bonus (the chance is shown); with neither it is a long shot, and a job beyond your reach won't see you at all. After a no, try again the next day; each no in a row at the same place waits longer, until you get better at what it asks for or a new season comes. Shower first: nobody hires someone who smells.": "Candidatar-se é uma rolagem: o que você faz bem e os traços que a vaga procura são seu bônus (a chance aparece); sem nenhum dos dois, é um tiro no escuro, e uma vaga fora do seu alcance nem te recebe. Depois de um não, tente de novo no dia seguinte; cada não seguido no mesmo lugar espera mais, até você melhorar no que pedem ou chegar uma nova estação. Tome banho antes: ninguém contrata quem está cheirando mal.",
 "Asking for work is a roll: what you are good at and the traits the trade looks for are your bonus (the chance is shown); with neither it is a long shot, and a trade beyond your reach won't see you at all. After a no, try again the next day; each no in a row at the same place waits longer, until you get better at what it asks for or a new season comes. Wash first: nobody takes on someone who smells.": "Pedir trabalho é uma rolagem: o que você faz bem e os traços que o ofício procura são seu bônus (a chance aparece); sem nenhum dos dois, é um tiro no escuro, e um ofício fora do seu alcance nem te recebe. Depois de um não, tente de novo no dia seguinte; cada não seguido no mesmo lugar espera mais, até você melhorar no que pedem ou chegar uma nova estação. Lave-se antes: ninguém aceita quem está cheirando mal.",
