 "Visitors: invite people over from the Calendar. They arrive about an hour later, ring the doorbell and stay until you say goodbye. You choose where each one sleeps.": "Visitas: convide pessoas pela Agenda. Elas chegam cerca de uma hora depois, tocam a campainha e ficam até você se despedir. Você escolhe onde cada uma dorme.",
 "Parties can have guests from outside, or happen somewhere out. Edit the guests on the party card, and ask someone to stay after the party.": "Festas podem ter convidados de fora ou acontecer fora de casa. Edite os convidados no cartão da festa e peça para alguém ficar depois.",
