 "Sleeping through a party or a date asks first, and Sleep until wakes you up just in time.": "Dormir na hora de uma festa ou encontro pergunta antes, e \"Dormir até\" te acorda bem na hora.",
 "Rain and storm sounds, with their own volume in Settings.": "Sons de chuva e tempestade, com volume próprio nas Configurações.",
 "Cards: sprites on the left or the right. Visual novel: the dialog box on the left, with the width you choose.": "Cartões: sprites à esquerda ou à direita. Novela visual: a caixa de diálogo à esquerda, com a largura que você escolher.",
 "This Home comes first in the menu and holds the Home settings. More kinds of family ties.": "Este Home vem primeiro no menu e guarda as configurações do Home. Mais tipos de laços familiares.",
 "Safety: world files and slash commands can no longer run code (thanks, coldasblues). A spouse added later now shows as Married.": "Segurança: arquivos de mundo e slash commands não conseguem mais rodar código (obrigado, coldasblues). Um cônjuge adicionado depois agora aparece como casado.",
 "Visitors": "Visitas",
 "Home: a new way to play. One house, the characters you choose, and no work, money or bills: just the people and the story.": "Home: um novo jeito de jogar. Uma casa, os personagens que você escolher, e nada de trabalho, dinheiro ou contas: só as pessoas e a história.",
 "A ready Home, The Shared House, or your own one made in the Home creator.": "Um Home pronto, The Shared House, ou um seu, feito no criador de Home.",
 "Houses with floors and a floor plan, Go out to take the story anywhere, Who lives here to move people in and out, and a dress code for each room.": "Casas com andares e planta, Sair para levar a história a qualquer lugar, Quem mora aqui para as pessoas se mudarem, e um código de vestimenta para cada cômodo.",
 "In a Home, the clock moves a little with each message. Click it to let time pass.": "Num Home, o relógio anda um pouco a cada mensagem. Clique nele para deixar o tempo passar.",
