 "Image Generation": "Geração de Imagens",
 "Draws pictures with SillyTavern's Image Generation. A picture button next to Send opens its options (the character, their face, you, the whole story, the last message, a background); the picture appears in the chat.": "Desenha imagens com a Geração de Imagens do SillyTavern. Um botão de imagem ao lado do Enviar abre as opções (o personagem, o rosto dele, você, a história toda, a última mensagem, um cenário); a imagem aparece no chat.",
 "Installed, but no image source is chosen: pick one in SillyTavern's Extensions → Image Generation.": "Instalada, mas nenhuma fonte de imagem foi escolhida: escolha uma em Extensões → Geração de Imagens do SillyTavern.",
 "This extension has no settings of its own in the Extensions tab.": "Esta extensão não tem configurações próprias na aba Extensões.",
 "· built into SillyTavern": "· já vem no SillyTavern",
 "Silence notices about characters without a voice{2}": "Silenciar avisos sobre personagens sem voz{2}",
 "TTS warns about each character with no voice, a disabled voice or one missing from the voice map. On: those notices are not shown.": "O TTS avisa sobre cada personagem sem voz, com voz desativada ou fora do mapa de vozes. Ligado: esses avisos não aparecem.",
 "(not recommended to turn off)": "(não recomendado desligar)",
 "Configure": "Configurar",
 "Yourself": "Você mesmo",
 "Your face": "Seu rosto",
