 "Read it aloud": "Ler em voz alta",
 "Enter": "Entrar",
 "Leave": "Sair",
 "Armor": "Armadura",
 "Floor {0}": "Andar {0}",
 "What Mundi sends to the AI": "O que o Mundi envia para a IA",
 "Sent with every reply, on top of your preset, the character cards and the chat. Only what is about this place and the people here.": "Enviado com cada resposta, além do seu preset, dos cards dos personagens e do chat. Só o que é sobre este lugar e as pessoas daqui.",
 "Token budget for Mundi · {4}": "Orçamento de tokens do Mundi · {4}",
 "Over the budget, Mundi leaves out the least important blocks first (rumors, then approval…). The scene basics are always sent.": "Acima do orçamento, o Mundi deixa de fora primeiro os blocos menos importantes (boatos, depois aprovação…). O básico da cena é sempre enviado.",
 "Blocks": "Blocos",
 "Rules of the scene": "Regras da cena",
 "Sent last, after everything else. Empty: Mundi's own rules (shown greyed). The note about the language of replies is added by itself.": "Enviado por último, depois de tudo. Vazio: as regras do próprio Mundi (mostradas em cinza). A nota sobre o idioma das respostas é adicionada sozinha.",
 "SillyTavern's context size is unlocked ({0}): set it to your model's real context in AI Response Configuration.": "O tamanho de contexto do SillyTavern está destravado ({0}): ajuste para o contexto real do seu modelo em AI Response Configuration.",
 "{0}% of your context size ({1} tokens).": "{0}% do seu tamanho de contexto ({1} tokens).",
 "no limit": "sem limite",
 "left out: over the budget": "deixado de fora: acima do orçamento",
 "nothing to send here": "nada a enviar aqui",
 "Always sent": "Sempre enviado",
 "your text": "seu texto",
 "Change the text": "Mudar o texto",
 "Back to Mundi's rules": "Voltar às regras do Mundi",
 "Hide the text": "Esconder o texto",
 "Show the text sent now": "Mostrar o texto enviado agora",
 "is what Mundi writes for this block; write around it (for example": "é o que o Mundi escreve para este bloco; escreva em volta dele (por exemplo",
 "), or leave it out to send only your words. Your text is sent only when the block has something to say. Empty: Mundi's own text.": "), ou deixe-o de fora para enviar só as suas palavras. Seu texto só é enviado quando o bloco tem algo a dizer. Vazio: o texto do próprio Mundi.",
