 "{4} people · {5} households": "{4} pessoas · {5} famílias",
 "No presets yet. A preset is a group of your characters with their households and relations, ready for any world.": "Nenhum preset ainda. Um preset é um grupo dos seus personagens com suas famílias e relações, pronto para qualquer mundo.",
 "My friends": "Meus amigos",
 "Nothing here depends on a world: when a new game starts from this preset, each world gives them homes, jobs and routines of its own.": "Nada aqui depende de um mundo: quando um jogo novo começa a partir deste preset, cada mundo dá a eles casas, empregos e rotinas próprias.",
 "How they see you": "Como eles te veem",
