 "Practice levels them up: each 2 levels are +1 on their rolls, each level pays more, and some jobs ask for them.": "Praticar sobe o nível: a cada 2 níveis, +1 nas rolagens; cada nível paga mais, e alguns empregos pedem eles.",
 "· top level": "· nível máximo",
 "You'll go to the {0}. You get a reminder an hour before.": "Você vai ao {0}. Você recebe um lembrete uma hora antes.",
 "Not going to the {0}.": "Não vai ao {0}.",
 "Dismiss": "Dispensar",
 "Studied today · day {2} of {3}": "Estudou hoje · dia {2} de {3}",
 "Learn a skill in a few days": "Aprenda uma habilidade em poucos dias",
 "What do you want to learn?": "O que você quer aprender?",
 "{0} Taking": "{0} Fazendo",
 ": day {2} of {3}. Study once a day, {4}.": ": dia {2} de {3}. Estude uma vez por dia, {4}.",
 "Drop it": "Largar",
 "Pay once, then study a little each day (2 h, {0}). Each day counts once. When you finish, you learn its traits for good: they help in every roll, and some jobs ask for a course.": "Pague uma vez, depois estude um pouco por dia (2 h, {0}). Cada dia conta uma vez. Ao terminar, você aprende os traços dele para sempre: eles ajudam em toda rolagem, e alguns empregos pedem um curso.",
 "{4} · {5} day{6} · {7}": "{4} · {5} dia{6} · {7}",
 "✓ Finished": "✓ Concluído",
 "In progress · {0}/{1}": "Em andamento · {0}/{1}",
 "Enroll · {3}": "Matricular · {3}",
 "Skills": "Habilidades",
 "Earned with life goals": "Conquistados com metas de vida",
 "Education": "Educação",
 "{9} Experience": "{9} Experiência",
 "{11} Skills and traits": "{11} Habilidades e traços",
 "Each trait that fits what you do is +2 on its roll (interviews, cooking, workouts…).": "Cada traço que combina com o que você faz é +2 na rolagem (entrevistas, cozinha, treinos…).",
 "{20} Life goals reached": "{20} Metas de vida alcançadas",
 "{23} Activity": "{23} Atividade",
 "Fitness {24}/100 · {25} meals cooked · {26} good workouts · {27} parties": "Forma física {24}/100 · {25} refeições cozinhadas · {26} bons treinos · {27} festas",
 "{1} · rank {2} of {3}": "{1} · cargo {2} de {3}",
 "No traits yet.": "Nenhum traço ainda.",
 "In progress · day {2} of {3}{4}": "Em andamento · dia {2} de {3}{4}",
 "· studied today": "· estudou hoje",
 "✓ Finished · {2}": "✓ Concluído · {2}",
 "Enrolled: {0}. Study once a day, {1}.": "Matriculado: {0}. Estude uma vez por dia, {1}.",
 "You dropped the course. What you studied is kept if you take it again.": "Você largou o curso. O que estudou fica guardado se fizer de novo.",
 "Words (lexicon)": "Palavras (léxico)",
 "Character creation": "Criação de personagem",
 "Customs & calendar": "Costumes e calendário",
 "Realm & factions": "Reino e facções",
 "Economy & skies": "Economia e céus",
 "People & routines": "Pessoas e rotinas",
 "About this {0}": "Sobre este {0}",
 "Up to {5} characters. Only you see it: it is not sent to the AI (the setting below is).": "Até {5} caracteres. Só você vê: não é enviado à IA (o cenário abaixo é).",
 "The picture on the {13}'s card. Best at 16:9 (1400 × 782).": "A imagem no card do {13}. Melhor em 16:9 (1400 × 782).",
 "Look: style and skin": "Visual: estilo e skin",
 "Mix them as you like: the rules and the people stay the same. Players can still pick another skin in their settings.": "Combine como quiser: as regras e as pessoas continuam iguais. Os jogadores ainda podem escolher outra skin nas configurações.",
 "Travel: 30 minutes inside a town, 2 hours between towns.": "Viagem: 30 minutos dentro de uma cidade, 2 horas entre cidades.",
 "Each part of the day can change what is open (Maps: a place's \"Closed at\"), what things cost out and about (Prices ×, empty = as listed) and how places, homes and maps look (a picture for each part of the day).": "Cada parte do dia pode mudar o que está aberto (Mapas: o \"Fechado às\" de um lugar), quanto as coisas custam na rua (Preços ×, vazio = como listado) e o visual de lugares, casas e mapas (uma imagem para cada parte do dia).",
 "Made for (the tag on its card)": "Feito para (a tag no card)",
 "Show every tab": "Mostrar todas as abas",
 "A Home hides Realm, Economy and RPG (a Home is always Life-Sim). Jobs and courses happen off-screen.": "Um Home esconde Reino, Economia e RPG (um Home é sempre Life-Sim). Empregos e cursos acontecem fora de cena.",
 "Premise (how the story starts: shown when the game begins, and told to the AI)": "Premissa (como a história começa: mostrada quando o jogo começa, e contada à IA)",
 "Or use a room's picture": "Ou use a imagem de um cômodo",
 "Style (the words of the game and the device)": "Estilo (as palavras do jogo e o aparelho)",
 "Skin (colors of the HUD)": "Skin (cores do HUD)",
 "The symbol goes after the amount (\"40 g\")": "O símbolo vem depois do valor (\"40 g\")",
 "×1 (1 real second = 1 game minute)": "×1 (1 segundo real = 1 minuto do jogo)",
 "Prices ×": "Preços ×",
 "What kind of world": "Que tipo de mundo",
 "How things work here": "Como as coisas funcionam aqui",
 "A system turned off is gone from the HUD, the {10} and what the AI is told, and the game stops running it. Saves keep its data: turn it back on and it picks up where it was.": "Um sistema desligado some do HUD, do {10} e do que a IA recebe, e o jogo para de rodá-lo. Os saves guardam os dados: ligue de novo e ele continua de onde parou.",
 "Realistic or fantasy: what it holds (magic, gods, familiars and weapons with a soul only in fantasy). {0}": "Realista ou fantasia: o que ele tem (magia, deuses, familiares e armas com alma só na fantasia). {0}",
 "Life-Sim and RPG: the ways it can be played (with both, the player chooses when starting). Realistic or fantasy: what it holds (magic, gods, familiars and weapons with a soul only in fantasy).": "Life-Sim e RPG: os jeitos de jogar (com os dois, o jogador escolhe ao começar). Realista ou fantasia: o que ele tem (magia, deuses, familiares e armas com alma só na fantasia).",
 "Game mode": "Modo de jogo",
 "How a new game starts (the player can pick another way the tags allow).": "Como um jogo novo começa (o jogador pode escolher outro jeito que as tags permitam).",
 "Custom: turn each need on or off in the Needs tab, and the systems below here.": "Personalizado: ligue ou desligue cada necessidade na aba Necessidades, e os sistemas aqui embaixo.",
 "On": "Ligado",
 "title=\"Its system is off (Systems, below)\"": "title=\"O sistema dele está desligado (Sistemas, abaixo)\"",
 "The device looks like": "O aparelho parece",
 "A phone (apps on a screen)": "Um celular (apps numa tela)",
 "A journal (an open book with pages)": "Um diário (um livro aberto com páginas)",
 "The social app is": "O app social é",
 "A social network (posts, likes and replies)": "Uma rede social (posts, curtidas e respostas)",
 "A notice board (notices; whoever answers writes you a letter)": "Um mural (avisos; quem responde te escreve uma carta)",
 "Messages are": "As mensagens são",
 "Text messages": "Mensagens de texto",
 "Letters carried by a courier": "Cartas levadas por um mensageiro",
 "How people write (what the AI is told for messages and posts)": "Como as pessoas escrevem (o que a IA recebe para mensagens e posts)",
 "Needs {0} on.": "Precisa de {0} ligado.",
 "Made for {0} worlds: off unless you turn it on.": "Feito para mundos {0}: desligado a menos que você ligue.",
 "Off: homes are free (the other bills stay).": "Desligado: as casas são de graça (as outras contas continuam).",
 "Only in the RPG mode": "Só no modo RPG",
 "Like health: out of Life-Sim worlds.": "Como a saúde: fora de mundos Life-Sim.",
 "Turned off in this world": "Desligado neste mundo",
 "You pass out… The bill is {cost}.": "Você desmaia… A conta é {cost}.",
 "A crisis after a while at zero": "Uma crise depois de um tempo em zero",
