 "An outing (off-screen)": "Uma saída (fora de cena)",
 "You leave for a while (work, errands, a night out) and come back: offered even when needs are off. Made for Homes.": "Você sai por um tempo (trabalho, recados, uma noitada) e volta: oferecido mesmo com as necessidades desligadas. Feito para Homes.",
