 "Goods": "Mercadorias",
 "Bought and sold at markets (places tagged shop). Cheap where they are made, dear where they are scarce; illegal ones can be found by guards. A good with id camping_gear lets you rest at camp in a storm.": "Compradas e vendidas em mercados (lugares com a tag shop). Baratas onde são feitas, caras onde são raras; as ilegais podem ser achadas pelos guardas. Uma mercadoria com id camping_gear deixa descansar no acampamento numa tempestade.",
 "Crafting": "Criação",
 "Recipes turn goods into goods at the right place (an id, a tag, part of a name, or home). Legendary ones make a named artifact.": "Receitas transformam mercadorias em mercadorias no lugar certo (um id, uma tag, parte de um nome, ou casa). As lendárias fazem um artefato com nome.",
 "Found deep in towers or won at auctions (a good of the kind \"a weapon with a will\").": "Achada nas profundezas das torres ou ganha em leilões (uma mercadoria do tipo \"uma arma com vontade\").",
