 "Beats (gains ground on)": "Vence (ganha terreno de)",
 "Secret (only shown once you have dealings with it)": "Secreta (só aparece quando você tiver negócios com ela)",
 "Shows, matches, fairs: on a weekday, every few weeks, at a place. They are in the calendar and you go if you want.": "Shows, jogos, feiras: num dia da semana, a cada poucas semanas, num lugar. Ficam no calendário e você vai se quiser.",
 "Practice levels them up (to 10): +1 on their rolls every 2 levels, more money each level, and jobs can ask for a level.": "Praticar sobe o nível (até 10): +1 nas rolagens a cada 2 níveis, mais dinheiro a cada nível, e empregos podem pedir um nível.",
 "A ladder of ranks (students first, the head last), tuition, lessons, exams and clubs. Its staff (the people who work at the place) are its faculty.": "Uma escada de cargos (alunos primeiro, o diretor por último), mensalidade, aulas, provas e clubes. Os funcionários (quem trabalha no lugar) são o corpo docente.",
