 "Carries (more goods)": "Carrega (mais mercadorias)",
 "The RPG mode needs the world's RPG: attributes, skills, classes (with a subclass at level 3 or 5), magic and titles. Start from the medieval one and change what you like, or from nothing.": "O modo RPG precisa do RPG do mundo: atributos, habilidades, classes (com uma subclasse no nível 3 ou 5), magia e títulos. Comece pelo medieval e mude o que quiser, ou do zero.",
