 "Daily wage per level": "Salário diário por nível",
 "Career paths": "Caminhos de carreira",
 "At some ranks (3, 6, 9 in the built-in careers) the player chooses a path; its ranks come next.{0}": "Em alguns cargos (3, 6, 9 nas carreiras prontas) o jogador escolhe um caminho; os cargos dele vêm a seguir.{0}",
 "Add a choice of paths": "Adicionar uma escolha de caminhos",
 "Ranks after rank {0} above are not used: the paths replace them.": "Os cargos depois do cargo {0} acima não são usados: os caminhos substituem.",
 "Remove these paths": "Remover estes caminhos",
 "Add a path": "Adicionar um caminho",
 "Choose at rank": "Escolher no cargo",
 "Traits that help on this path": "Traços que ajudam neste caminho",
 "Remove this path": "Remover este caminho",
 "Path": "Caminho",
 "Shifts to reach it": "Turnos para chegar",
 "Only after (empty: after any)": "Só depois de (vazio: depois de qualquer)",
 "Players pay once, then study a little each day (at home or where a place is tagged \"study\"). When they finish, they learn the course's traits for good.": "Os jogadores pagam uma vez, depois estudam um pouco por dia (em casa ou onde um lugar tem a tag \"study\"). Ao terminar, aprendem os traços do curso para sempre.",
 "{2} days · {3}": "{2} dias · {3}",
 "aria-disabled=\"true\" title=\"Give the course a trait to teach first\"": "aria-disabled=\"true\" title=\"Dê ao curso um traço para ensinar antes\"",
 "Required for these jobs": "Obrigatório para estes empregos",
 "Helps in these jobs (faster promotions)": "Ajuda nestes empregos (promoções mais rápidas)",
 "Improves these skills (+2 on their roll)": "Melhora estas habilidades (+2 na rolagem)",
 "Area": "Área",
 "Days of study": "Dias de estudo",
 "Price ({0})": "Preço ({0})",
 "Teaches these traits": "Ensina estes traços",
 "Separated by commas. A trait can be new; it helps wherever it is asked for.": "Separados por vírgula. Um traço pode ser novo; ele ajuda onde for pedido.",
 "Traits of this world: {0}": "Traços deste mundo: {0}",
 "No jobs yet.": "Nenhum emprego ainda.",
 "No things to do with a roll yet (Things to do → a roll).": "Nenhuma coisa para fazer com rolagem ainda (Coisas para fazer → uma rolagem).",
 "No courses yet.": "Nenhum curso ainda.",
 "Mood when you wake up at home (+)": "Humor ao acordar em casa (+)",
 "Trips take this share of the time (0.5 = half; empty = not a vehicle)": "As viagens levam esta parte do tempo (0.5 = metade; vazio = não é veículo)",
 "Unlocks: {0}.": "Desbloqueia: {0}.",
 "Unlocks nothing to do yet: in Things to do, pick this item under \"Only if the player owns\".": "Ainda não desbloqueia nada: em Coisas para fazer, escolha este item em \"Só se o jogador tiver\".",
 "Nothing for sale.": "Nada à venda.",
 "phone, rent, course…": "celular, aluguel, curso…",
 "Words of the game": "Palavras do jogo",
 "Every term the game shows or tells the AI, as the {0} style says it. Write your world's own word to replace it (a phone can be a \"Den Den Mushi\", a course \"training\"…); leave it empty to keep the style's. {0}, {1}… are filled in by the game (a name, a price…). Apps, places, jobs and needs are named in their own tabs.": "Todo termo que o jogo mostra ou diz à IA, do jeito que o estilo {0} fala. Escreva a palavra do seu mundo para substituir (um celular pode ser um \"Den Den Mushi\", um curso \"treinamento\"…); deixe vazio para manter a do estilo. {0}, {1}… são preenchidos pelo jogo (um nome, um preço…). Apps, lugares, empregos e necessidades têm nome nas próprias abas.",
 "{2} term{3} changed in this world.": "{2} termo{3} mudado{3} neste mundo.",
 "Nothing matches.": "Nada corresponde.",
 "Expenses (besides the rent)": "Despesas (além do aluguel)",
 "Bills every home pays each week with the rent: water, power, firewood, servants, taxes… as many as you like, or none. Each kind of home sets its own amount above. One left unpaid for a week stops the things you pick here.": "Contas que toda casa paga por semana com o aluguel: água, luz, lenha, criados, impostos… quantas quiser, ou nenhuma. Cada tipo de casa define o próprio valor acima. Uma sem pagar por uma semana para as coisas que você escolher aqui.",
 "Things that break at home": "Coisas que quebram em casa",
 "Now and then one of these breaks and stops some things until it is fixed (by the player, or paying someone).": "De vez em quando uma destas quebra e para algumas coisas até ser consertada (pelo jogador, ou pagando alguém).",
 "{1} homes · {2}": "{1} casas · {2}",
 "{5} homes placed. They are numbered (House 1, House 2…).": "{5} casas posicionadas. Elas são numeradas (Casa 1, Casa 2…).",
 "Inside at other times of the day": "Por dentro em outras horas do dia",
 "{0} a week ({1})": "{0} por semana ({1})",
 "Use the usual one": "Usar a de sempre",
 "stops {0} thing{1}": "para {0} coisa{1}",
 "stops nothing": "não para nada",
 "When it is a week unpaid, it stops": "Com uma semana sem pagar, para",
 "Like the upkeep of arms and gear: not billed in Life-Sim.": "Como a manutenção de armas e equipamento: não é cobrada no Life-Sim.",
 "Name (empty: the Words tab's word)": "Nome (vazio: a palavra da aba Palavras)",
 "Message when it stops (optional; {app} = where to pay)": "Mensagem quando para (opcional; {app} = onde pagar)",
 "{0} was not paid for a week: it stopped until you pay it.": "{0} não foi pago por uma semana: parou até você pagar.",
 "Message when it is paid again (optional)": "Mensagem quando é pago de novo (opcional)",
 "No expenses: homes only pay the rent.": "Sem despesas: as casas só pagam o aluguel.",
 "Paying someone to fix it costs ({0})": "Pagar alguém para consertar custa ({0})",
 "stops {1}": "para {1}",
 "While broken, it stops": "Enquanto quebrado, para",
 "Name (as in \"Oh no: … broke at home\")": "Nome (como em \"Ah não: … quebrou em casa\")",
 "Nothing breaks.": "Nada quebra.",
 "What the player chooses": "O que o jogador escolhe",
 "The parts of making a character this world asks for (a new character or a persona). Turned off, it is not asked: the first origin is used, and no traits or words about you.": "As partes da criação de personagem que este mundo pede (um personagem novo ou uma persona). Desligado, não é perguntado: a primeira origem é usada, e nenhum traço ou palavras sobre você.",
 "A picture": "Uma imagem",
 "New characters only.": "Só personagens novos.",
 "Money, home and (RPG) skills.": "Dinheiro, casa e (RPG) habilidades.",
 "Traits": "Traços",
 "The groups below.": "Os grupos abaixo.",
 "A few words of their own.": "Algumas palavras próprias.",
 "In the RPG": "No RPG",
 "Trained skills": "Habilidades treinadas",
 "What it gives you": "O que te dá",
 "Folk hero: common folk take you in.": "Herói do povo: o povo te acolhe.",
 "People of this world": "Pessoas deste mundo",
 "Each becomes a character card when a game of this world starts. Their job, home and routine say where they are each hour.": "Cada uma vira um card de personagem quando um jogo deste mundo começa. O emprego, a casa e a rotina dizem onde ela está a cada hora.",
 "Shuffle everyone's job, home and routine": "Embaralhar emprego, casa e rotina de todos",
 "Goes out to (free time)": "Sai para (tempo livre)",
 "Relations": "Relações",
 "How {9} relates to the world's other people (any of them, wherever they live), from the start of every game.": "Como {9} se relaciona com as outras pessoas do mundo (qualquer uma, onde quer que more), desde o começo de todo jogo.",
