 "Something else": "Outra coisa",
 "Go skateboarding, read a book, call my mom…": "Andar de skate, ler um livro, ligar pra minha mãe…",
 "What do you want to do?": "O que você quer fazer?",
 "For how long?": "Por quanto tempo?",
 "A one-time thing: it passes the time, lifts your mood a little, and goes into your journal.": "Uma coisa única: passa o tempo, melhora um pouco o humor e vai para o seu diário.",
 "{u} spent some time doing this: {0}.": "{u} passou um tempo fazendo isto: {0}.",
 "{0} minutes": "{0} minutos",
 "{0} hours": "{0} horas",
 "(and {0})": "(e {0})",
 "their usual clothes": "as roupas de sempre",
 "Dress code": "Código de vestimenta",
 "What people wear in each room: the name of an outfit folder in their Expressions (a \"swimsuit\" folder for the pool, \"pajamas\" for the bedrooms…). Anyone who has it puts it on while in that room with you, as far as their comfort goes (Library › Expressions: how bold they go, and how bold each outfit is), and the AI is told; anyone it's too bold for, or who doesn't have it, keeps their clothes. Empty: their usual clothes.": "O que as pessoas vestem em cada cômodo: o nome de uma pasta de roupa nas Expressions delas (uma pasta \"swimsuit\" para a piscina, \"pajamas\" para os quartos…). Quem tiver veste enquanto estiver nesse cômodo com você, até onde o conforto de cada um vai (Biblioteca › Expressões: o quanto a pessoa ousa e o quanto cada roupa é ousada), e a IA fica sabendo; para quem for ousado demais, ou quem não tiver, continua com a roupa. Vazio: as roupas de sempre.",
 "Bedrooms": "Quartos",
