 "Bid tonight": "Dar lance hoje à noite",
 "Closed.": "Fechado.",
 "the bank": "o banco",
 "a shady moneylender": "um agiota suspeito",
 "Time passes with each message": "O tempo passa a cada mensagem",
 "Each message you send is {1} minutes. Off: time only moves with \"Let time pass\", sleeping and what you do.": "Cada mensagem que você envia são {1} minutos. Desligado: o tempo só anda com \"Deixar o tempo passar\", dormindo e com o que você faz.",
 "The housemates leave the house": "Os moradores saem de casa",
 "For work, errands and nights out (off-screen), then they come back. Off: everyone stays in.": "Para trabalhar, resolver coisas e sair à noite (fora de cena), depois voltam. Desligado: todo mundo fica em casa.",
 "The job is what the AI is told they do. With a shift they are out of the house during it (when the housemates leave the house).": "O emprego é o que a IA fica sabendo que a pessoa faz. Com um turno, ela fica fora de casa durante ele (quando os moradores saem de casa).",
 "Job (optional): nurse, barista…": "Emprego (opcional): enfermeira, barista…",
 "Lives with you": "Mora com você",
