 "Out": "Fora",
 "Play as {2}": "Jogar como {2}",
 "Call them over": "Chamar para cá",
 "Go to where they are": "Ir até onde está",
 "aria-disabled=\"true\" title=\"Too little to come on their own\"": "aria-disabled=\"true\" title=\"Pequeno demais para vir sozinho\"",
