 "Nobody lives here. Move someone in from another household.": "Ninguém mora aqui. Traga alguém de outra família.",
 "Search a person or an address (or type empty)": "Buscar uma pessoa ou um endereço (ou digite vazio)",
 "Move {0}": "Mudar {0}",
 "Choose the new bedroom. Moving in with someone means sharing the room.": "Escolha o novo quarto. Ir morar com alguém significa dividir o quarto.",
 "Choose the new home. Moving in with others makes them one household.": "Escolha a nova casa. Ir morar com outros faz de vocês uma família.",
