 "Your relations": "Suas relações",
 "How you start with anyone in this world, not only who lives with you: a best friend across town, a rival, an old enemy, someone you are dating.": "Como você começa com qualquer um neste mundo, não só quem mora com você: um melhor amigo do outro lado da cidade, um rival, um velho inimigo, alguém com quem você namora.",
 "Between any two people of the house (or with you): siblings, friends, a couple, married, exes, rivals…": "Entre quaisquer duas pessoas da casa (ou com você): irmãos, amigos, um casal, casados, ex, rivais…",
 "Between any two people, in any household (or with you): friends, rivals, enemies, allies, a couple…": "Entre quaisquer duas pessoas, de qualquer família (ou com você): amigos, rivais, inimigos, aliados, um casal…",
 "None yet.": "Nenhuma ainda.",
 "You and": "Você e",
 "Choose the people of this world first.": "Escolha as pessoas deste mundo antes.",
 "The people who live with you: family, a partner, roommates. They share your home and your wallet, and you can play as any of them later (\"Play as\").": "As pessoas que moram com você: família, um parceiro, colegas de casa. Elas dividem sua casa e sua carteira, e você pode jogar como qualquer uma depois (\"Jogar como\").",
 "is your": "é seu",
 "You live alone for now.": "Você mora sozinho por enquanto.",
 "Only the characters you brought yourself are here: the world's own people already have their homes and families.": "Aqui só estão os personagens que você trouxe: as pessoas do próprio mundo já têm suas casas e famílias.",
 "lives with you: your start": "mora com você: seu começo",
 "Your start has you living with them; to live with someone else, change the start (\"Who you live with\"). You can still add people.": "Seu começo faz você morar com eles; para morar com outra pessoa, mude o começo (\"Com quem você mora\"). Você ainda pode adicionar pessoas.",
