 "Floor plan": "Planta",
 "Optional. With a floor plan, the house map in the game is a plan of the house: one per floor, each room where it really is. Without one, the game shows the pictures of the rooms (as now).": "Opcional. Com uma planta, o mapa da casa no jogo é uma planta da casa: uma por andar, cada cômodo onde ele realmente está. Sem uma, o jogo mostra as imagens dos cômodos (como agora).",
