 "On the plan": "Na planta",
 "Rooms light up with": "Os cômodos acendem com",
 "The boxes you draw here are the rooms: in the game, a room lights up when the mouse is over it, and a click goes there.": "As caixas que você desenha aqui são os cômodos: no jogo, um cômodo acende quando o mouse passa por cima, e um clique vai até ele.",
 "Rooms {20}": "Cômodos {20}",
