 "Reads the characters' lines aloud with SillyTavern's voices. Adds a speaker button to each line; automatic narration keeps working as set up in SillyTavern.": "Lê em voz alta as falas dos personagens com as vozes do SillyTavern. Adiciona um botão de alto-falante em cada fala; a narração automática continua como configurada no SillyTavern.",
 "Installed, but turned off: enable it in SillyTavern's Extensions → TTS.": "Instalada, mas desligada: ative em Extensões → TTS do SillyTavern.",
 "Speech Recognition": "Reconhecimento de fala",
 "Talk instead of typing: a microphone button next to Send. What you say goes into the message box (or is sent, if the extension is set to send by itself).": "Fale em vez de digitar: um botão de microfone ao lado de Enviar. O que você fala vai para a caixa de mensagem (ou é enviado, se a extensão estiver configurada para enviar sozinha).",
 "Installed, but no speech provider is chosen: pick one in SillyTavern's Extensions → Speech Recognition.": "Instalada, mas sem provedor de fala escolhido: escolha um em Extensões → Speech Recognition do SillyTavern.",
 "Add-ons": "Complementos",
 "SillyTavern extensions that Mundi supports. Mundi checks by itself whether each one is installed; when it is, its button appears in the scene.": "Extensões do SillyTavern que o Mundi suporta. O Mundi verifica sozinho se cada uma está instalada; quando está, o botão dela aparece na cena.",
