 "SillyTavern lorebooks this world uses, like lorebooks linked to the game's group: they are switched on while you play one of its games (besides the lorebook Mundi writes from the Lore tab).": "Lorebooks do SillyTavern que este mundo usa, como lorebooks vinculados ao grupo do jogo: ficam ligados enquanto você joga um jogo dele (além do lorebook que o Mundi escreve a partir da aba Lore).",
 "Author's Note": "Nota do Autor",
 "You have no lorebooks yet.": "Você ainda não tem lorebooks.",
