 "Relationships": "Relacionamentos",
 "Romance": "Romance",
 "How fast feelings grow. The first points with someone come at full speed; after that each gain counts a little less, and the pace comes back over the next hours. Nothing ever stops completely.": "A rapidez com que os sentimentos crescem. Os primeiros pontos com alguém vêm em velocidade total; depois, cada ganho conta um pouco menos, e o ritmo volta nas horas seguintes. Nada para de vez.",
 "Friendship: points at full speed": "Amizade: pontos em velocidade total",
 "Friendship: points more until half speed": "Amizade: pontos a mais até a metade da velocidade",
 "Romance: points at full speed": "Romance: pontos em velocidade total",
