 "The pace comes back by half in": "O ritmo volta pela metade em",
 "{0} h": "{0} h",
 "Show the numbers (debug)": "Mostrar os números (depuração)",
 "The raw values, how fast each relationship grows right now, and what each message changed, with undo. For tuning: the AI never sees it.": "Os valores exatos, a rapidez com que cada relacionamento cresce agora e o que cada mensagem mudou, com desfazer. Para ajustes: a IA nunca vê isso.",
 "Turn on \"Advanced\" for how fast feelings grow and the debug view.": "Ative \"Avançado\" para a rapidez com que os sentimentos crescem e a visão de depuração.",
