 "New gender": "Novo gênero",
 "Genders": "Gêneros",
 "Everyone can have one of these (or none). Who people are attracted to is set per gender.": "Cada pessoa pode ter um destes (ou nenhum). Por quem cada um se sente atraído é definido por gênero.",
 "Plural (for the AI)": "Plural (para a IA)",
 "Pronouns": "Pronomes",
 "No genders: nobody has one, and attraction does nothing.": "Sem gêneros: ninguém tem um, e a atração não faz nada.",
 "Add a gender": "Adicionar um gênero",
 "Their ways": "O jeito de ser",
 "Where every game of this world starts from (a card's own Mundi settings come first). Unset: the defaults.": "De onde cada jogo deste mundo parte (as configurações Mundi do próprio card vêm primeiro). Sem definir: o padrão.",
 "Who they are": "Quem são",
 "Each one's gender and, under \"More\", who they are attracted to, how fast their feelings grow and how they are about intimacy. Taken from their card when it has Mundi settings; the cards are not changed.": "O gênero de cada um e, em \"Mais\", por quem sente atração, a rapidez com que os sentimentos crescem e como lida com a intimidade. Vem do card quando ele tem configurações Mundi; os cards não são alterados.",
 "More": "Mais",
 "Less": "Menos",
 "Gender and attraction": "Gênero e atração",
 "The gender and pronouns of the people here (and yours), and who they are attracted to when it is not everyone.": "O gênero e os pronomes das pessoas aqui (e os seus), e por quem se sentem atraídas quando não é por todos.",
 "Attracted to": "Sente atração por",
 "Everyone (default)": "Todos (padrão)",
 "Only: {0}": "Só: {0}",
 "No one": "Ninguém",
 "How fast feelings grow toward each gender (100% is normal, 0% never). Losses are never changed.": "A rapidez com que os sentimentos crescem por cada gênero (100% é o normal, 0% nunca). As perdas nunca mudam.",
 "Turn on \"Advanced\" for who you are attracted to.": "Ative \"Avançado\" para escolher por quem você sente atração.",
 "Suggest from the cards": "Sugerir pelos cards",
 "{0} without a gender. Your AI reads each card once (gender, attraction, intimacy); nothing changes until you apply it.": "{0} sem gênero. Sua IA lê cada card uma vez (gênero, atração, intimidade); nada muda até você aplicar.",
 "Everyone has a gender.": "Todos têm um gênero.",
 "Reading {0}'s card ({1}/{2})…": "Lendo o card de {0} ({1}/{2})…",
 "The card does not say.": "O card não diz.",
 "attracted to: {0}": "sente atração por: {0}",
 "attracted to no one": "não sente atração por ninguém",
 "only with a partner": "só com um par",
 "Apply all": "Aplicar tudo",
 "Save to card": "Salvar no card",
 "Their gender, attraction, pace and styles go to their card's Mundi settings, so new games with them start from these. Nothing else on the card changes.": "O gênero, a atração, o ritmo e os estilos vão para as configurações Mundi do card, e novos jogos com essa pessoa partem deles. Nada mais no card muda.",
 "Saved to {0}'s card.": "Salvo no card de {0}.",
 "Could not save the character.": "Não foi possível salvar o personagem.",
 "Nothing changes until you apply what your AI read.": "Nada muda até você aplicar o que sua IA leu.",
 "Their initiatives": "Iniciativas deles",
 "Characters take the initiative": "Os personagens tomam a iniciativa",
 "Rarely": "Raramente",
 "Normal (default)": "Normal (padrão)",
 "Often": "Com frequência",
 "People open up, confess, ask you out, text you, warn you before they leave and hold grudges on their own. Normal: at most one thing they start on their own a day, and every few days per person. Off: none of it.": "As pessoas se abrem, se declaram, te chamam para sair, mandam mensagem, avisam antes de terminar e guardam mágoa por conta própria. Normal: no máximo uma coisa por dia que elas começam sozinhas, e a cada poucos dias por pessoa. Desligado: nada disso.",
 "Asks you to come over tonight": "Te convida para ir à casa dele(a) hoje à noite",
 "Not yet": "Ainda não",
 "Not tonight, but soon?": "Hoje não, mas logo?",
 "You said no to {0}.": "Você disse não a {0}.",
 "They are still upset with you.": "Ainda está chateado(a) com você.",
 "What the people here bring up on their own this scene (opening up, a confession, asking you something), and what each one wants from you.": "O que as pessoas aqui puxam por conta própria nesta cena (se abrir, uma confissão, te pedir algo), e o que cada uma quer de você.",
 "Needs some time": "Precisa de um tempo",
 "Their feelings have grown a lot lately: more will come, slowly, after some time.": "Os sentimentos cresceram muito nos últimos tempos: mais virá, devagar, depois de um tempo.",
 "You have grown close quickly lately: more will come, slowly, after some time.": "Vocês se aproximaram rápido nos últimos tempos: mais virá, devagar, depois de um tempo.",
 "Opinions spread through friends": "As opiniões se espalham entre amigos",
 "Someone who adores you, or can't stand you, talks about you to their close friends, and slowly colors what they think of you (never worse than wary, by talk alone).": "Quem te adora, ou não te suporta, fala de você com os amigos próximos e, aos poucos, muda o que eles pensam de você (nunca pior que desconfiado, só por conversa).",
 "Speakers' colors": "Cores de quem fala",
 "Color each speaker's dialogue": "Colorir as falas de cada personagem",
 "Quotes (\"…\") in a line, and the speaker's name, take that person's color. Leave it off if your preset or regex scripts already color quotes. The narrator keeps the quoted text color.": "As falas entre aspas (\"…\") de uma mensagem, e o nome de quem fala, ficam com a cor dessa pessoa. Deixe desligado se o seu preset ou seus scripts de regex já colorem as aspas. O narrador mantém a cor do texto entre aspas.",
 "Open a game to see its people's colors.": "Abra um jogo para ver as cores das pessoas dele.",
 "Pick colors again": "Escolher as cores de novo",
 "Your AI is choosing colors…": "Sua IA está escolhendo as cores…",
 "Your AI could not choose: automatic colors are used for now.": "Sua IA não conseguiu escolher: por enquanto são usadas cores automáticas.",
 "Colors set on a card (or yours) stay; your AI chooses the others, and Mundi keeps them readable and apart.": "As cores definidas num card (ou a sua) ficam; sua IA escolhe as outras, e o Mundi as mantém legíveis e diferentes entre si.",
 "Your choice": "Sua escolha",
