 "your sibling": "seu irmão ou irmã",
 "your cousin": "seu primo ou prima",
 "Friendship as usual": "Amizade como de costume",
 "My start": "Meu começo",
 "Premise (how the story starts; the AI is told this)": "Premissa (como a história começa; a IA fica sabendo disto)",
 "Who you are, why you're here, and what's going on as the story begins. Write {{user}} for yourself.": "Quem você é, por que está aqui e o que está acontecendo quando a história começa. Escreva {{user}} para você.",
 "A job to start with": "Um emprego para começar",
 "Whom you already know": "Quem você já conhece",
 "The world's people who know you from the start, and how (only those in the game; your own characters are under \"Your relations\").": "As pessoas do mundo que te conhecem desde o início, e como (só as que estão no jogo; seus próprios personagens ficam em \"Suas relações\").",
 "Nobody yet.": "Ninguém ainda.",
 "Someone you know": "Alguém que você conhece",
 "Or let your AI write the premise from lorebooks": "Ou deixe sua IA escrever a premissa a partir de lorebooks",
 "Give the start a name first.": "Dê um nome ao começo primeiro.",
