 "Start deleted.": "Começo apagado.",
 "Starts": "Começos",
 "No starts yet. Write a custom start in a new game and choose \"Save as a start\": it shows up here, for that world's next games.": "Nenhum começo ainda. Escreva um começo personalizado em um jogo novo e escolha \"Salvar como começo\": ele aparece aqui, para os próximos jogos desse mundo.",
 "Choose a start to change it.": "Escolha um começo para alterá-lo.",
 "World lore": "Lore do mundo",
 "the world's own limit ({0})": "o limite do próprio mundo ({0})",
 "{0} rows": "{0} linhas",
 "at most {0} rows": "no máximo {0} linhas",
 "A busy place can match many lore rows: over the limit, the rows about the people here come first, then this place, then its area, then the season, weather and time.": "Um lugar movimentado pode combinar com muitas linhas de lore: acima do limite, vêm primeiro as linhas sobre as pessoas daqui, depois este lugar, depois a região, depois a estação, o clima e a hora.",
