 "You bought the {0}.": "Você comprou {0}.",
 "That isn't sold here.": "Isso não é vendido aqui.",
 "Each job has its days and hours: your week is in the Calendar, and you get a reminder before each shift. Choose how hard you work; if you have plans, you can work part of the shift and then go. Some jobs pay extra at night or for overtime.": "Cada emprego tem seus dias e horários: sua semana fica na Agenda, e você recebe um lembrete antes de cada turno. Escolha o quanto você se esforça; se tiver planos, pode trabalhar parte do turno e depois ir. Alguns empregos pagam mais à noite ou por hora extra.",
 "Performance and days off": "Desempenho e folgas",
 "Good shifts raise your performance; missing a shift, coming in late and slacking lower it. Book vacation days or call in sick ahead. How strict all this is depends on the work rules (This world → World).": "Bons turnos aumentam seu desempenho; faltar a um turno, chegar atrasado e fazer corpo mole o diminuem. Marque dias de férias ou avise que está doente com antecedência. O quanto isso é rígido depende das regras de trabalho (Este mundo → Mundo).",
 "The next rank asks for shifts and time in your rank, a good performance and sometimes skills: the work screen and the Jobs app show what is missing. The top of a career takes about a game year.": "O próximo cargo pede turnos e tempo no seu cargo, um bom desempenho e às vezes habilidades: a tela de trabalho e o app Trabalhos mostram o que falta. O topo de uma carreira leva cerca de um ano de jogo.",
 "Career speed (×; 2: twice as fast)": "Velocidade da carreira (×; 2: duas vezes mais rápida)",
