 "Never badly": "Nunca mal",
 "How much pressure jobs put on you: days, absences, lateness, days off, how fast careers go. A preset sets them all; changing one rule makes it Custom.": "Quanta pressão os empregos colocam em você: dias, faltas, atrasos, folgas, a velocidade das carreiras. Um modelo define tudo isso; mudar uma regra o torna Personalizado.",
 "(default)": "(padrão)",
 "Your own mix of the rules (Advanced).": "Sua própria mistura das regras (Avançado).",
 "After the last train": "Depois do último trem",
 "Career speed": "Velocidade da carreira",
 "(2×: careers twice as fast)": "(2×: carreiras duas vezes mais rápidas)",
 "Work hard": "Trabalhar duro",
 "Your performance grows fastest, with a chance of a bonus. More tiring, a bit stressful.": "Seu desempenho cresce mais rápido, com chance de bônus. Mais cansativo e um pouco estressante.",
 "Chat with coworkers": "Conversar com os colegas",
 "Better mood, closer to the colleagues on shift with you. Performance grows slowly.": "Melhor humor, mais perto dos colegas de turno com você. O desempenho cresce devagar.",
 "Take it easy": "Pegar leve",
 "Less tiring, but your performance drops and the boss notices.": "Menos cansativo, mas seu desempenho cai e o chefe percebe.",
 "Every job keeps its real days. A missed shift costs you, lateness counts after 15 minutes, and low performance can get you fired.": "Cada emprego mantém seus dias reais. Um turno perdido te custa, o atraso conta depois de 15 minutos, e o desempenho baixo pode te fazer ser demitido.",
 "About three quarters of the days, paid more per shift so a week earns the same. Gentler on absences and lateness; careers a little faster.": "Cerca de três quartos dos dias, com mais pagamento por turno para a semana render o mesmo. Mais tolerante com faltas e atrasos; carreiras um pouco mais rápidas.",
 "About half the days, paid more per shift so a week earns the same. Skip a shift whenever you like; nothing at work goes badly; careers faster.": "Cerca de metade dos dias, com mais pagamento por turno para a semana render o mesmo. Pule um turno quando quiser; nada de ruim acontece no trabalho; carreiras mais rápidas.",
