 "{0}: {1}% back at the end, and you stay a season after.": "{0}: {1}% devolvido no fim, e você fica uma estação depois.",
 "Drop it? What you paid is gone. Enroll again within a year and half your classes count (once).": "Largar o curso? O que você pagou não volta. Matricule-se de novo em até um ano e metade das suas aulas conta (uma vez).",
 "Yes, drop it": "Sim, largar",
 "Keep it": "Manter",
 "Taking {0} of 2. One class a day for each, {1}.": "Fazendo {0} de 2. Uma aula por dia em cada, {1}.",
 "Taking {0} of 2. Two at once is slower: each class counts less. One class a day for each, {1}.": "Fazendo {0} de 2. Dois ao mesmo tempo é mais lento: cada aula vale menos. Uma aula por dia em cada, {1}.",
 "Pay, then go to class: a course lasts weeks and has a set number of classes (2 h each, {0}). Every class teaches you a little of its skills, and finishing gives you their levels for good. You can miss a few classes; miss too many and the course runs long, or you fail. Some jobs ask for a course first.": "Pague e vá às aulas: um curso dura semanas e tem um número fixo de aulas (2 h cada, {0}). Cada aula ensina um pouco das suas habilidades, e terminar o curso dá os níveis delas para sempre. Você pode faltar a algumas aulas; faltas demais alongam o curso, ou você é reprovado. Alguns empregos pedem um curso antes.",
 "any five days a week": "quaisquer cinco dias por semana",
 "Paid when you enroll and at the start of each season; unpaid, the course waits.": "Pago na matrícula e no início de cada estação; sem pagamento, o curso espera.",
 "Needs: {0}": "Precisa: {0}",
 "Needs: you have it ✓": "Precisa: você já tem ✓",
 "{0} of {1} classes clash with your shifts (a missed class: no excuse for work).": "{0} de {1} aulas coincidem com seus turnos (aula perdida: trabalho não é desculpa).",
 "With two courses at once, each class counts less: about {0} more.": "Com dois cursos ao mesmo tempo, cada aula vale menos: cerca de {0} a mais.",
 "Taking it": "Fazendo",
 "Asks for {0} first.": "Pede {0} antes.",
 "You can take two courses at most. Finish or drop one first.": "Você pode fazer no máximo dois cursos. Termine ou largue um antes.",
 "{0}: {1} of the fee paid for you.": "{0}: {1} da taxa pago por você.",
