 "{0}: {1} of the fee paid for you, if you stay a season at your job after finishing.": "{0}: {1} da taxa pago por você, se você ficar uma estação no emprego depois de terminar.",
 "{0}: {1} of the fee back when you finish, if you stay a season at your job after finishing.": "{0}: {1} da taxa devolvido quando você terminar, se ficar uma estação no emprego depois.",
 "{0}: {1} of the fee paid for you, if you stay a season at it after finishing.": "{0}: {1} da taxa pago por você, se você ficar uma estação lá depois de terminar.",
 "{0}: {1} of the fee back when you finish, if you stay a season at it after finishing.": "{0}: {1} da taxa devolvido quando você terminar, se ficar uma estação lá depois.",
 "Enrolled: {0}. {1} over about {2} {3}. One class a day at most, {4}.": "Matriculado: {0}. {1} em cerca de {2} {3}. No máximo uma aula por dia, {4}.",
 "Enrolled: {0}. One class a day at most, {1}.": "Matriculado: {0}. No máximo uma aula por dia, {1}.",
 "You dropped the course. Enroll again within a year and half your classes count (once).": "Você largou o curso. Matricule-se de novo em até um ano e metade das suas aulas conta (uma vez).",
 "Nothing to pay.": "Nada a pagar.",
 "This course is not offered any more.": "Este curso não é mais oferecido.",
 "You are already taking this course.": "Você já está fazendo este curso.",
 "You already finished this course.": "Você já terminou este curso.",
 "This course asks for {0} first.": "Este curso pede {0} antes.",
 "{0} courses finished": "{0} cursos concluídos",
 "more": "mais",
 "You are not taking this course.": "Você não está fazendo este curso.",
 "You already studied today. Come back tomorrow.": "Você já estudou hoje. Volte amanhã.",
 "The fee for {0} is unpaid ({1}): the course is on hold.": "A taxa de {0} não foi paga ({1}): o curso está em espera.",
 "{0} is taught at {1}.": "{0} é dado em {1}.",
 "You can study at home or at a place for it.": "Você pode estudar em casa ou num lugar próprio para isso.",
 "Too late for a class today: a class takes two hours and must end before midnight.": "Tarde demais para uma aula hoje: uma aula dura duas horas e precisa acabar antes da meia-noite.",
 "There is no class today.": "Não há aula hoje.",
 "Class is {0}.": "A aula é {0}.",
 "You are due at work then.": "Você tem trabalho nesse horário.",
 "a make-up class, {0}": "uma aula de reposição, {0}",
 "a make-up class (charged by the class if it runs into a new season)": "uma aula de reposição (cobrada por aula se cair numa nova estação)",
 "{0}: you are {1} {2} behind with {3} {4} left (one class a day): too many to make up. The course will fail when it ends.": "{0}: {1} {2} de atraso, faltando {3} {4} (uma aula por dia): demais para repor. Você será reprovado quando o curso acabar.",
 "{0}: you are {1} {2} behind with {3} {4} left (one class a day). One more day without a class and you fail the course.": "{0}: {1} {2} de atraso, faltando {3} {4} (uma aula por dia). Mais um dia sem aula e você é reprovado no curso.",
 "{0}: you are {1} {2} behind with {3} {4} left (one class a day): that uses all {5} free missed {6}. Each further one adds {7}.": "{0}: {1} {2} de atraso, faltando {3} {4} (uma aula por dia): isso usa todas as {5} faltas sem penalidade. Cada falta a mais acrescenta {7}.",
 "{0}: you are {1} {2} behind with {3} {4} left (one class a day): that uses all {5} free missed {6} and adds make-up classes. Each further one adds {7}.": "{0}: {1} {2} de atraso, faltando {3} {4} (uma aula por dia): isso usa todas as {5} faltas sem penalidade e acrescenta aulas de reposição. Cada falta a mais acrescenta {7}.",
 "{0}: you are {1} {2} behind with {3} {4} left (one class a day): that uses {5} of {6} free missed classes.": "{0}: {1} {2} de atraso, faltando {3} {4} (uma aula por dia): isso usa {5} de {6} faltas sem penalidade.",
 "{0}: one more missed class and you fail the course ({1} of {2} make-up classes used).": "{0}: mais uma falta e você é reprovado no curso ({1} de {2} aulas de reposição usadas).",
 "{0}: you have used all {1} free missed {2}. The next one adds {3}.": "{0}: você usou todas as {1} faltas sem penalidade. A próxima acrescenta {3}.",
 "{0}: you have missed {1} of {2} free classes.": "{0}: você faltou a {1} de {2} aulas sem penalidade.",
 "You failed {0}: too many missed classes. What you learned stays, but there is no certificate. If you enroll again within a year, half the classes you attended count (once).": "Você foi reprovado em {0}: faltas demais. O que aprendeu fica, mas não há certificado. Se você se matricular de novo em até um ano, metade das aulas que assistiu conta (uma vez).",
 "{0}: class {1} of {2} done.": "{0}: aula {1} de {2} concluída.",
 "{0}: class {1} of {2} done. You can still miss {3} without a penalty.": "{0}: aula {1} de {2} concluída. Você ainda pode faltar {3} sem penalidade.",
 "You finished {0}! Skills: {1}. {2} paid back {3}.": "Você terminou {0}! Habilidades: {1}. {2} devolveu {3}.",
 "You finished {0}! Skills: {1}. You promised {2} to stay a season: leaving sooner pays back the rest of it.": "Você terminou {0}! Habilidades: {1}. Você prometeu a {2} ficar uma estação: sair antes devolve o resto.",
 "You paid {0} for {1}: classes go on.": "Você pagou {0} por {1}: as aulas continuam.",
 "You paid {0}: classes go on.": "Você pagou {0}: as aulas continuam.",
 "You have paid back your course sponsorship.": "Você terminou de devolver o patrocínio do curso.",
 "You left before the season you promised {0}: you owe them {1}.": "Você saiu antes da estação que prometeu a {0}: deve {1} a eles.",
 "You left before the season you promised {0}: you owe them {1} ({2} still to pay).": "Você saiu antes da estação que prometeu a {0}: deve {1} a eles ({2} ainda a pagar).",
 "{0} is on hold until you pay {1}.": "{0} está em espera até você pagar {1}.",
 "Course: {0}": "Curso: {0}",
