 "{0}: {1} over about {2} {3}, {4}. Fee {5}.": "{0}: {1} em cerca de {2} {3}, {4}. Taxa {5}.",
 "{0}: {1} over about {2} {3}, {4}. Fee {5}. {6}": "{0}: {1} em cerca de {2} {3}, {4}. Taxa {5}. {6}",
 "Study: {0}": "Estudar: {0}",
 "Pay what you owe for {0}": "Pagar o que deve de {0}",
 "{u} enrolled in a course: {0}.": "{u} se matriculou num curso: {0}.",
 "{0} helped {u} with the course \"{1}\".": "{0} ajudou {u} com o curso \"{1}\".",
