 "New bottom ranks added (ids)": "Novos cargos de base adicionados (ids)",
 "Added a rank below the first one after people played this job? Add a new id here once: saved games holding this job move up one rank, so they keep the rank they had.": "Adicionou um cargo abaixo do primeiro depois que as pessoas jogaram com este emprego? Adicione um id novo aqui uma vez: os jogos salvos com este emprego sobem um cargo, e assim mantêm o cargo que tinham.",
 "The first rank is a student rank": "O primeiro cargo é de estudante",
 "You can be hired at it while you take the course this job asks for; the next rank needs the course finished.": "Você pode ser contratado nele enquanto faz o curso que este emprego pede; o cargo seguinte exige o curso concluído.",
