 "adult option": "opção adulta",
 "What a character can do, in levels 1–10: jobs, ranks, courses and rolls ask for them, and strengths start them. Hobbies (Customs & calendar) count as skills too.": "O que um personagem sabe fazer, em níveis de 1 a 10: empregos, cargos, cursos e rolagens pedem habilidades, e os pontos fortes as iniciam. Os passatempos (Costumes e calendário) também contam como habilidades.",
 "Like Sensuality: hidden from the profile, the AI and conditions otherwise. Whatever asks for it or trains it must be adult too.": "Como Sensualidade: sem isso fica escondida do perfil, da IA e das condições. O que a pede ou a treina também precisa ser adulto.",
