 "They won't serve you here this week. {0} more days.": "Aqui não vão te atender esta semana. Mais {0} dias.",
 "They won't serve you here this week. 1 more day.": "Aqui não vão te atender esta semana. Mais 1 dia.",
 "Bills are weekly. One left unpaid for a week is cut off until you pay what is overdue (for the rent, you are locked out of your home). You can pay part of a bill at any time.": "As contas são semanais. Uma conta sem pagar por uma semana é cortada até você pagar o que está atrasado (no caso do aluguel, você fica trancado fora de casa). Você pode pagar parte de uma conta a qualquer momento.",
 "Bills are weekly. One left unpaid for a week stops until you pay what is overdue (for the rent, the landlord locks you out). You can pay part of a bill at any time.": "As contas são semanais. Uma conta sem pagar por uma semana para até você pagar o que está atrasado (no caso do aluguel, o senhorio te tranca fora). Você pode pagar parte de uma conta a qualquer momento.",
 "You are locked out: pay {1} of rent {0} to get back in.": "Você está trancado fora: pague {1} de aluguel {0} para voltar a entrar.",
 "The landlord locked you out: pay {1} of rent {0} to get back in.": "O senhorio te trancou fora: pague {1} de aluguel {0} para voltar a entrar.",
 "Pay {1} {0} to get back in": "Pague {1} {0} para voltar a entrar",
 "Last day for the rent: pay {1} {2} today, or you will be locked out tomorrow.": "Último dia do aluguel: pague {1} {2} hoje, ou amanhã você fica trancado fora.",
 "Last day for the rent: pay {1} {2} today, or the landlord locks you out tomorrow.": "Último dia do aluguel: pague {1} {2} hoje, ou amanhã o senhorio te tranca fora.",
 "Last day for {0}: pay {1} {2} today, or it is cut off tomorrow.": "Último dia para {0}: pague {1} {2} hoje, ou amanhã é cortado.",
 "Last day for {0}: pay {1} {2} today, or it stops tomorrow.": "Último dia para {0}: pague {1} {2} hoje, ou amanhã para.",
 "{0} are weekly bills: pay them {1} (they turn red when due). One left unpaid for a week stops (or, for the rent, you are locked out of your home) until you pay what is overdue; you can pay part of a bill, and one that stopped owes no more weeks.": "{0} são contas semanais: pague {1} (ficam vermelhas no vencimento). Uma sem pagar por uma semana para (ou, no caso do aluguel, você fica trancado fora de casa) até você pagar o que está atrasado; você pode pagar parte de uma conta, e uma que parou não acumula mais semanas.",
 "Locked out tomorrow": "Trancado fora amanhã",
