 "You graduated: {0}, with distinction (GPA {1})! A ceremony at {2}, a photo with the class.": "Você se formou: {0}, com distinção (CR {1})! Uma cerimônia em {2}, uma foto com a turma.",
 "You graduated: {0}, with distinction (GPA {1})! A ceremony at {2}, a photo with the class. A distinguished degree starts you a rank up as: {3}.": "Você se formou: {0}, com distinção (CR {1})! Uma cerimônia em {2}, uma foto com a turma. Um diploma com distinção faz você começar um cargo acima como: {3}.",
