 "Giving it as a gift uses it up.": "Dar de presente faz você perdê-lo.",
 "It counts with someone along: someone you invited, or with you already.": "Conta com alguém junto: alguém que você convidou, ou que já está com você.",
 "It counts when the roll goes well ({0} helps).": "Conta quando a rolagem dá certo ({0} ajuda).",
 "It counts when the roll goes well.": "Conta quando a rolagem dá certo.",
 "{0} is rolled in things like {1}.": "Rola-se {0} em coisas como {1}.",
 "Book a night away from home: {0}.": "Reserve uma noite fora de casa: {0}.",
