 "Jobs that train it: {0}.": "Trabalhos que treinam isso: {0}.",
 "It also grows by itself while you're out among people.": "Também cresce sozinho enquanto você está na rua entre as pessoas.",
 "Ask for the job at {0}.": "Peça o emprego em {0}.",
 "Apply in the Jobs app, under Openings.": "Candidate-se no app Trabalhos, em Vagas.",
 "It wants {0} to hire you.": "Pede {0} para contratar você.",
 "It needs the course {0}.": "Precisa do curso {0}.",
 "To be hired, one of: {0}.": "Para ser contratado, uma destas: {0}.",
 "To be hired: {0}.": "Para ser contratado: {0}.",
 "You become a regular at a place after {0} visits.": "Você vira frequentador de um lugar depois de {0} visitas.",
 "You become a regular after {0} visits ({1} so far).": "Você vira frequentador depois de {0} visitas ({1} até agora).",
 "Book a night at {0} and sleep there.": "Reserve uma noite em {0} e durma lá.",
 "Places near home where you are a regular": "Lugares perto de casa onde você é frequentador",
 "Places where you are a regular in {0}": "Lugares onde você é frequentador em {0}",
 "Your gender (default)": "Seu gênero (padrão)",
 "attracted to everyone": "sente atração por todos",
 "Drawn to your gender if you are drawn to theirs, otherwise straight; still drawn to anyone they are or were with.": "Sente atração pelo seu gênero se você sente pelo dela; se não, é hétero; ainda sente por quem está ou esteve junto.",
 "Yours only sorts the dating app: while you play someone, their own feelings wait. It counts again once you stop playing them.": "A sua só ordena o app de namoro: enquanto você joga como alguém, os sentimentos dessa pessoa esperam. Volta a valer quando você deixa de jogar como ela.",
 "Yours sorts the dating app and, when the game starts, decides who is drawn to you: of the people set to “Your gender”, the share you choose for their gender are (all of them at 100%, about half at 50%); the others are straight.": "A sua ordena o app de namoro e, quando o jogo começa, decide quem sente atração por você: das pessoas com “Seu gênero”, a parte que você escolhe para o gênero delas sente (todas a 100%, cerca de metade a 50%); as outras são héteros.",
 "Being in the same place isn't being together: what you do on your own, the narrator tells, and the people here go on with their own things. Someone may come over now and then (friends more often, and more in a bar than a library): talk, or nod and keep going. Talk to someone and they're with you for a while. \"Keep to myself\" in Things to do: only friends come over, and rarely.": "Estar no mesmo lugar não é estar junto: o que você faz sozinho, o narrador conta, e as pessoas aqui seguem com as coisas delas. De vez em quando alguém pode vir até você (amigos com mais frequência, e mais num bar do que numa biblioteca): converse, ou acene e continue. Converse com alguém e essa pessoa fica com você por um tempo. \"Ficar na minha\" em O que fazer: só amigos vêm até você, e raramente.",
