 "{0} so far · you ran it {1} · rent {2} a week": "{0} até agora · você tocou {1} · aluguel de {2} por semana",
 "Open every day: hired hands keep it going when you're not there ({0}% of a day you run it yourself). About {1} a week if you run it two days.": "Aberto todo dia: os funcionários tocam quando você não está ({0}% de um dia em que você mesmo toca). Cerca de {1} por semana se você tocar dois dias.",
 "Open only while you run it yourself: go there and run the counter. About {0} a week if you run it four days.": "Aberto só enquanto você mesmo toca: vá até lá e toque o balcão. Cerca de {0} por semana se você tocar quatro dias.",
