 "A fuller division makes each shift count for more and the summer and winter bonuses larger. The board looks at it when the season ends.": "Uma divisão mais completa faz cada turno valer mais e aumenta os bônus de verão e de inverno. O conselho olha para ela quando a estação termina.",
 "A season: {0}% against {1}%": "Uma estação: {0}% contra {1}%",
 "Choose its style": "Escolha o estilo",
 "Once for this tier: about the same money, different guests, different stories, and some upgrades only one style finds.": "Uma vez neste nível: mais ou menos o mesmo dinheiro, outros clientes, outras histórias, e algumas melhorias que só um estilo encontra.",
 "Changing it is a renovation: {0}.": "Mudar é uma reforma: {0}.",
