 "Each costs more than the last of its number. Many are found around Tokyo, or earned; money only buys what's there.": "Cada uma custa mais que a anterior do mesmo número. Muitas se encontram por Tóquio, ou se conquistam; o dinheiro só compra o que está ali.",
