 "Running a business is off in this world (Features › Systems): none of this plays until it is on.": "Tocar um negócio está desligado neste mundo (Recursos › Sistemas): nada disto entra no jogo até ser ligado.",
 "Ventures": "Empreendimentos",
 "Something the player can own or run (a café, a hotel, an executive's division), growing like an incremental game: its numbers raised for good by upgrades, discoveries and events inside the ceiling of its tier.": "Algo que o jogador pode ter ou comandar (um café, um hotel, uma divisão de executivo), crescendo como um jogo incremental: seus números sobem de vez com melhorias, descobertas e eventos, dentro do teto do seu nível.",
