 "A takeover, a purchase, a partnership, a lease (one of each at most, any of them a way in), or none: an executive's division opens with the job's rank.": "Assumir um negócio, comprar, uma sociedade, alugar (um de cada no máximo, qualquer um serve de entrada) ou nenhum: a divisão de um executivo abre com o cargo no emprego.",
