 "Chosen once at their tier: their words lay over the place's for the AI, their multipliers shift the numbers a little, and some upgrades are found only with them.": "Escolhidos uma vez no seu nível: suas palavras se sobrepõem às do lugar para a IA, seus multiplicadores mexem um pouco nos números, e algumas melhorias só se encontram com eles.",
