 "Upgrades found only with it": "Melhorias encontradas só com ele",
 "Add a style": "Adicionar um estilo",
 "Points added to one number for good, at a price, from a tier on: bought from the app, turned up in the city (what a street story's or an event's choice turns up), or opened by a condition.": "Pontos somados de vez a um número, por um preço, a partir de um nível: comprada no app, encontrada pela cidade (o que a escolha de uma história de rua ou de um evento faz aparecer) ou aberta por uma condição.",
