 "Off: nobody spends their free time here (a love hotel).": "Desligado: ninguém passa o tempo livre aqui (um love hotel).",
 "Its button for running it yourself (empty: the café's)": "O botão para você mesmo tocar (vazio: o do café)",
 "The button's icon (an emoji)": "O ícone do botão (um emoji)",
