 "A job it ends": "Um emprego que ele encerra",
 "Paid off over time": "Pago aos poucos",
 "Paid off over time: part of the price at once, the rest out of the weekly takings (never your own money)": "Pago aos poucos: parte do preço na hora, o resto do faturamento semanal (nunca do seu dinheiro)",
 "Paid at once (a share of the price, 0 … 1)": "Pago na hora (uma fração do preço, 0 … 1)",
