 "rank {0} in your job": "cargo {0} no seu emprego",
 "Can we talk soon? It's about something I've kept to myself.": "A gente pode conversar logo? É sobre uma coisa que guardei só para mim.",
 "It's still on my mind. Could we meet this week?": "Ainda estou pensando nisso. A gente pode se encontrar esta semana?",
 "I have to decide soon, and I'd like to talk to you first.": "Preciso decidir logo e queria conversar com você antes.",
 "Storylines now wait for you. A backup of the save was kept (Settings → Game → This save).": "As tramas agora esperam por você. Um backup do save foi guardado (Configurações → Jogo → Este save).",
 "Storylines now wait for you: 1 person you haven't met yet will start theirs when you get to know them. A backup of the save was kept (Settings → Game → This save).": "As tramas agora esperam por você: 1 pessoa que você ainda não conheceu vai começar a própria trama quando você a conhecer. Um backup do save foi guardado (Configurações → Jogo → Este save).",
 "Storylines now wait for you: {0} people you haven't met yet will start theirs when you get to know them. A backup of the save was kept (Settings → Game → This save).": "As tramas agora esperam por você: {0} pessoas que você ainda não conheceu vão começar a própria trama quando você as conhecer. Um backup do save foi guardado (Configurações → Jogo → Este save).",
 "Storylines now wait for you: 1 storyline under way will end in a scene with you. A backup of the save was kept (Settings → Game → This save).": "As tramas agora esperam por você: 1 trama em andamento vai terminar em uma cena com você. Um backup do save foi guardado (Configurações → Jogo → Este save).",
 "Storylines now wait for you: {0} storylines under way will end in a scene with you. A backup of the save was kept (Settings → Game → This save).": "As tramas agora esperam por você: {0} tramas em andamento vão terminar em uma cena com você. Um backup do save foi guardado (Configurações → Jogo → Este save).",
 "Storylines now wait for you: 1 person you haven't met yet will start theirs when you get to know them, and 1 storyline under way will end in a scene with you. A backup of the save was kept (Settings → Game → This save).": "As tramas agora esperam por você: 1 pessoa que você ainda não conheceu vai começar a própria trama quando você a conhecer, e 1 trama em andamento vai terminar em uma cena com você. Um backup do save foi guardado (Configurações → Jogo → Este save).",
 "Storylines now wait for you: 1 person you haven't met yet will start theirs when you get to know them, and {0} storylines under way will end in a scene with you. A backup of the save was kept (Settings → Game → This save).": "As tramas agora esperam por você: 1 pessoa que você ainda não conheceu vai começar a própria trama quando você a conhecer, e {0} tramas em andamento vão terminar em uma cena com você. Um backup do save foi guardado (Configurações → Jogo → Este save).",
 "Storylines now wait for you: {0} people you haven't met yet will start theirs when you get to know them, and 1 storyline under way will end in a scene with you. A backup of the save was kept (Settings → Game → This save).": "As tramas agora esperam por você: {0} pessoas que você ainda não conheceu vão começar a própria trama quando você as conhecer, e 1 trama em andamento vai terminar em uma cena com você. Um backup do save foi guardado (Configurações → Jogo → Este save).",
 "Storylines now wait for you: {0} people you haven't met yet will start theirs when you get to know them, and {1} storylines under way will end in a scene with you. A backup of the save was kept (Settings → Game → This save).": "As tramas agora esperam por você: {0} pessoas que você ainda não conheceu vão começar a própria trama quando você as conhecer, e {1} tramas em andamento vão terminar em uma cena com você. Um backup do save foi guardado (Configurações → Jogo → Este save).",
