 "It fits no home for sale (its size, kinds and areas).": "Não cabe em nenhuma casa à venda (tamanho, tipos e áreas).",
 "It needs itself.": "Precisa de si mesma.",
 "That place isn't a room of this fixture: in Maps & places, make it one.": "Esse lugar não é cômodo desta comodidade: em Mapas e lugares, faça dele um.",
 "The same id as a shop item.": "O mesmo id de um item da loja.",
 "Offered when (a condition; empty: always)": "Oferecida quando (uma condição; vazio: sempre)",
 "The Homes app offers it only while it holds; kept once bought.": "O app Moradia só a oferece enquanto valer; depois de comprada, fica.",
 "Up to three, each within ±10% (a flat amount within ±1), counted with the shop's things: only the best one of each kind counts. They work in the home it's in: the one you live in, or your second home while you're there.": "Até três, cada um dentro de ±10% (um valor fixo dentro de ±1), contados com as coisas da loja: só a melhor de cada tipo conta. Valem na casa onde ela está: aquela em que você mora, ou sua segunda casa enquanto estiver lá.",
 "Its words (optional; empty: its name)": "Suas palavras (opcional; vazio: o nome)",
 "a black grand piano by the window": "a black grand piano by the window",
 "At a home you own: \"It has …\", the dearest five.": "Numa casa sua: \"It has …\", as cinco mais caras.",
 "Always": "Sempre",
 "These two matter for an adult one, told under the shop's rules; the others are named in the home's own line.": "Estes dois importam para uma adulta, contada pelas regras da loja; as outras são citadas na linha da própria casa.",
