 "About {0}": "Cerca de {0}",
 "On show in its wing": "Em exposição na sua ala",
 "In the first room: {0}": "Na primeira sala: {0}",
 "In the cases at home: {0}": "Nas vitrines de casa: {0}",
 "Boxed: {0}": "Em caixas: {0}",
 "to show it all": "para expor tudo",
 "Tier {0} of {1}": "Nível {0} de {1}",
 "the next at {0}%": "o próximo aos {0}%",
 "the next: {0}": "o próximo: {0}",
 "the next one later": "o próximo, mais tarde",
 "the last": "o último",
 "Closer in tiers: the first once {0}": "Mais próximos por níveis: o primeiro pede {0}",
 "Closer in tiers, later": "Mais próximos por níveis, mais tarde",
 "Not yet: being together waits until {0}.": "Ainda não: para ficarem juntos, falta {0}.",
 "Not yet: being together waits.": "Ainda não: ficarem juntos vai ter de esperar.",
 "The museum": "O museu",
 "Display pieces (art, crafts, things of the city) come from finds, shops, festival stalls, people's storylines and more. Your first one begins a museum of your own: its tabs come first in the app.": "Peças de exposição (arte, artesanato, coisas da cidade) vêm de achados, lojas, barracas de festival, tramas das pessoas e mais. A primeira começa um museu seu: as abas dele vêm primeiro no app.",
 "Cases at home": "Vitrines em casa",
 "Until you have a museum, your {0} dearest pieces sit in glass cases at home and the rest are boxed. Every piece counts for the museum's percentage as soon as it's yours, wherever it is.": "Até você ter um museu, suas {0} peças mais caras ficam em vitrines em casa e o resto em caixas. Cada peça conta para a porcentagem do museu assim que é sua, esteja onde estiver.",
 "Your own museum": "Um museu seu",
 "Keep collecting and": "Continue colecionando e",
 "may be offered to you: take it on in the Museum tab, paid once, with no weekly upkeep. Its first room shows {0} pieces from any hall.": "pode ser oferecido a você: assuma-o na aba Museu, pago uma vez, sem manutenção semanal. A primeira sala expõe {0} peças de qualquer salão.",
 "Wings and upgrades": "Alas e melhorias",
 "A wing puts a whole hall on show. Other upgrades bring renown, a place to read or have tea, and room for what needs it: some pieces wait for a climate room, security or a night guard, and their tiles say so.": "Uma ala põe um salão inteiro em exposição. Outras melhorias trazem renome, um lugar para ler ou tomar chá, e espaço para o que precisa dele: algumas peças esperam uma sala climatizada, segurança ou um vigia noturno, e os cartões delas dizem isso.",
 "Renown and visitors": "Renome e visitantes",
 "Pieces on show, upgrades, shows and the museum's milestones bring renown. Each level opens more (the Museum tab says what the next one brings), and every Monday the visitors pay a little.": "Peças expostas, melhorias, exposições e os marcos do museu trazem renome. Cada nível abre mais coisas (a aba Museu diz o que o próximo traz), e toda segunda os visitantes pagam um pouco.",
 "The dealer": "A marchand",
 "Once the museum is yours a dealer calls every {0} days with a few pieces, on sale until her next visit. No piece waits too long for its turn. You can ask her for one piece at a time: it comes within two visits, a little dearer.": "Quando o museu for seu, uma marchand passa a cada {0} dias com algumas peças, à venda até a próxima visita dela. Nenhuma peça espera demais pela sua vez. Você pode pedir a ela uma peça de cada vez: chega em até duas visitas, um pouco mais cara.",
 "The sales": "Os leilões",
 "Sales come four times a year, with a catalogue a week before. Set a top bid for each lot by phone, or be in the saleroom as it starts to raise once more if you are outbid. Another collector bids too; a lot she takes comes back later, dearer.": "Os leilões acontecem quatro vezes por ano, com um catálogo uma semana antes. Defina um lance máximo para cada lote por telefone, ou esteja na sala do leilão quando começar para subir mais uma vez se cobrirem seu lance. Outra colecionadora também dá lances; um lote que ela leva volta depois, mais caro.",
 "Damaged pieces and replicas": "Peças danificadas e réplicas",
 "A find can come damaged: it counts once the restoration workshop has restored it. A piece whose only chance has passed can be made as a replica by the workshop: it fills the slot at half the renown, and the real piece replaces it if it ever comes.": "Um achado pode vir danificado: conta depois que a oficina de restauração o restaurar. Uma peça cuja única chance já passou pode ser feita como réplica pela oficina: preenche o espaço com metade do renome, e a peça verdadeira a substitui se um dia vier.",
 "Shows": "Exposições",
 "With an exhibition hall, open a show once a season on a theme with at least {0} pieces on show: more renown while it's on, and a little for good the first time each theme is shown.": "Com uma sala de exposições, abra uma exposição por estação sobre um tema com pelo menos {0} peças expostas: mais renome enquanto durar, e um pouco para sempre na primeira vez que cada tema é exposto.",
 "Where the piece comes from (any one way)": "De onde a peça vem (qualquer um dos caminhos)",
 "Add a way to have it": "Adicionar um caminho para tê-la",
 "Comes from": "Vem de",
 "No ways yet: a piece needs at least one (or a condition, as a memento).": "Nenhum caminho ainda: uma peça precisa de pelo menos um (ou de uma condição, como uma memória).",
 "Found after a thing to do (or any at some places)": "Achada depois de algo para fazer (ou qualquer coisa em alguns lugares)",
 "Sold at places": "Vendida em lugares",
 "A festival's stall, every year": "Uma barraca de festival, todo ano",
 "The dealer brings it": "A marchand a traz",
 "A lot at the sales": "Um lote nos leilões",
 "A storyline's end (any ending)": "O fim de uma trama (qualquer final)",
 "A milestone (free, once a condition holds)": "Um marco (grátis, quando uma condição se cumpre)",
 "A replica from the curator's workshop": "Uma réplica da oficina do(a) curador(a)",
 "After this thing to do": "Depois desta coisa para fazer",
 "(none: any thing to do at its places)": "(nenhuma: qualquer coisa para fazer nos lugares dela)",
 "Storyline": "Trama",
 "Street story": "História de rua",
 "Or any thing to do at these places": "Ou qualquer coisa para fazer nestes lugares",
 "Estimate ({0})": "Estimativa ({0})",
 "Chance after it (0 … 1)": "Chance depois disso (0 … 1)",
 "How rare (0 … 1; empty: 1, as likely as any)": "Raridade (0 … 1; vazio: 1, tão provável quanto qualquer outra)",
 "Odds it comes damaged (0 … 1; it counts once the workshop restores it)": "Chance de vir danificada (0 … 1; conta quando a oficina a restaurar)",
 "When it comes (a condition)": "Quando vem (uma condição)",
 "Offered once (a condition: its one-time way has passed)": "Oferecida uma vez (uma condição: o caminho único dela já passou)",
 "Only while (a condition; optional)": "Só enquanto (uma condição; opcional)",
 "Price on the empty tile ({0}; optional)": "Preço no cartão vazio ({0}; opcional)",
 "Needs an upgrade of the museum": "Precisa de uma melhoria do museu",
 "A bonus piece": "Uma peça bônus",
 "Shown in a gold frame and never counted in a percentage, so it can come after 100%.": "Mostrada numa moldura dourada e nunca contada numa porcentagem, então pode vir depois dos 100%.",
 "Plaque (one line about the piece, shown once it's yours; optional)": "Placa (uma linha sobre a peça, mostrada quando ela for sua; opcional)",
 "Hokusai's great wave off Kanagawa.": "A grande onda de Kanagawa, de Hokusai.",
 "Pick a kind of source.": "Escolha um tipo de origem.",
 "Its chance is 0 … 1.": "A chance vai de 0 … 1.",
 "Only a find can come damaged.": "Só um achado pode vir danificado.",
 "It needs a price.": "Precisa de um preço.",
 "A find needs a thing to do or places.": "Um achado precisa de uma coisa para fazer ou de lugares.",
 "No thing to do called {0}.": "Nenhuma coisa para fazer chamada {0}.",
