 "Pick a festival.": "Escolha um festival.",
 "No festival called {0}.": "Nenhum festival chamado {0}.",
 "The world has no museum: nobody brings it.": "O mundo não tem museu: ninguém a traz.",
 "The museum has no dealer.": "O museu não tem marchand.",
 "The museum has no sales.": "O museu não tem leilões.",
 "Pick a storyline.": "Escolha uma trama.",
 "No storyline called {0}.": "Nenhuma trama chamada {0}.",
 "A milestone needs a condition.": "Um marco precisa de uma condição.",
 "Pick a street story or write a condition (seen: x:n).": "Escolha uma história de rua ou escreva uma condição (seen: x:n).",
 "No street story called {0}.": "Nenhuma história de rua chamada {0}.",
 "A replica needs a condition: when its one-time way has passed.": "Uma réplica precisa de uma condição: quando o caminho único já passou.",
 "No upgrade of the museum is a workshop, so no one makes it.": "Nenhuma melhoria do museu é uma oficina, então ninguém a faz.",
 "A display piece with no source and no condition can never be had.": "Uma peça de exposição sem origem e sem condição nunca pode ser obtida.",
 "It needs the upgrade {0}, but the world has no museum: ignored.": "Precisa da melhoria {0}, mas o mundo não tem museu: ignorado.",
 "The museum has no upgrade called {0}.": "O museu não tem melhoria chamada {0}.",
 "Its only ways can pass (a milestone, a story): give it a second one (the dealer, a shop, a replica).": "Os únicos caminhos dela podem passar (um marco, uma história): dê a ela um segundo (a marchand, uma loja, uma réplica).",
 "A bonus piece with a condition fills like a record slot.": "Uma peça bônus com condição se preenche como um espaço do registro.",
 "Add a museum": "Adicionar um museu",
 "Remove the museum": "Remover o museu",
 "A museum of your own: a place hidden until it's yours, an offer to take it on, upgrades and wings, renown and visitors, a dealer and sales. Without one, display halls are a plain collection (finds, shops, festivals, endings, stories, milestones).": "Um museu seu: um lugar escondido até ser seu, uma oferta para assumi-lo, melhorias e alas, renome e visitantes, uma marchand e leilões. Sem ele, os salões de exposição são uma coleção simples (achados, lojas, festivais, finais, histórias, marcos).",
 "Pieces you own sit in cases at home until the museum is taken on; its first room shows some of any hall, and each wing puts a whole hall on show. Upgrades raise its renown, renown brings visitors and their money each week.": "As peças que você tem ficam em vitrines em casa até o museu ser assumido; a primeira sala expõe algumas de qualquer salão, e cada ala põe um salão inteiro em exposição. As melhorias aumentam o renome, e o renome traz visitantes e o dinheiro deles toda semana.",
 "Its place (hidden until it is yours)": "O lugar dele (escondido até ser seu)",
 "It can be taken on once (a condition)": "Pode ser assumido uma vez (uma condição)",
 "Its price ({0})": "O preço dele ({0})",
 "Pieces on show at home before it opens (cases)": "Peças expostas em casa antes de ele abrir (vitrines)",
 "Pieces its first room shows (any hall, before wings)": "Peças que a primeira sala expõe (de qualquer salão, antes das alas)",
 "Its curator": "Curador(a)",
 "The job the opening gives them": "O emprego que a abertura dá a essa pessoa",
 "(their own)": "(o próprio)",
 "No upgrades yet.": "Nenhuma melhoria ainda.",
 "a wing": "uma ala",
 "What it does, in a line (optional)": "O que faz, numa linha (opcional)",
 "Renown it adds (optional)": "Renome que acrescenta (opcional)",
 "A wing: puts this hall on show": "Uma ala: põe este salão em exposição",
 "(not a wing)": "(não é uma ala)",
 "What else it does": "O que mais faz",
 "(nothing more: renown, or a wing)": "(nada mais: renome, ou uma ala)",
 "A climate room (pieces that need it)": "Uma sala climatizada (peças que precisam dela)",
 "Security (pieces that need it)": "Segurança (peças que precisam dela)",
 "A night guard (pieces that need it; stops a theft)": "Um vigia noturno (peças que precisam dele; impede um roubo)",
 "A workshop (restores damaged pieces, makes replicas)": "Uma oficina (restaura peças danificadas, faz réplicas)",
 "A reading room (finds come more often)": "Uma sala de leitura (achados vêm mais vezes)",
 "An exhibition hall (shows)": "Uma sala de exposições (exposições)",
 "Needs these upgrades first": "Precisa destas melhorias antes",
