 "A lot that comes back costs more by (0.2: +20%)": "Um lote que volta custa a mais (0.2: +20%)",
 "More lots from a renown level": "Mais lotes a partir de um nível de renome",
 "The rival who bids against you": "A rival que dá lances contra você",
