 "Tiers and who they're drawn to": "Níveis e por quem sente atração",
 "Drawn only to the player": "Atração só pelo jogador",
 "Whatever the player's gender, and to no one else: no romance with anyone else forms by itself, not on the dating app, never leaves the maps.": "Seja qual for o gênero do jogador, e por mais ninguém: nenhum romance com outra pessoa se forma sozinho, nem no app de namoro, e nunca sai dos mapas.",
 "Tiers open one after another, each the first time its condition holds, and are never lost (tier: {0} 2 holds from the third). Each caps how close they let the player come; before the first is reached, its caps already hold.": "Os níveis se abrem um depois do outro, cada um na primeira vez que a condição dele se cumpre, e nunca se perdem (tier: {0} 2 vale a partir do terceiro). Cada um limita o quanto a pessoa deixa o jogador se aproximar; antes de chegar ao primeiro, os limites dele já valem.",
