 "Nature and the dig": "A natureza e a escavação",
 "Some pieces come only in their season and at their hour: insects, fish and flowers turn up while you look for them in the parks, by the water and where things bloom.": "Algumas peças só vêm na estação e na hora delas: insetos, peixes e flores aparecem enquanto você os procura nos parques, perto da água e onde as coisas florescem.",
 "A missing piece marked In season can come now, and its hall says how many; the Here tab says what could turn up where you are.": "Uma peça que falta marcada Da estação pode vir agora, e o salão dela diz quantas são; a aba Aqui diz o que pode aparecer onde você está.",
 "Gear from the shop adds a little to the roll.": "O equipamento da loja melhora um pouco as chances.",
 "Some wait for": "Algumas esperam",
 ", as their tiles say.": ", como dizem os cartões delas.",
 "comes back every spring: dig or sift with the team on as many days as you like.": "volta toda primavera: escave ou peneire com a equipe quantos dias quiser.",
 "comes back every summer: dig or sift with the team on as many days as you like.": "volta todo verão: escave ou peneire com a equipe quantos dias quiser.",
 "comes back every autumn: dig or sift with the team on as many days as you like.": "volta todo outono: escave ou peneire com a equipe quantos dias quiser.",
 "comes back every winter: dig or sift with the team on as many days as you like.": "volta todo inverno: escave ou peneire com a equipe quantos dias quiser.",
 "comes back every {0}: dig or sift with the team on as many days as you like.": "volta a cada {0}: escave ou peneire com a equipe quantos dias quiser.",
 "comes back in its season: dig or sift with the team on as many days as you like.": "volta na sua temporada: escave ou peneire com a equipe quantos dias quiser.",
 "{0} days in one season make sure of a find, and at most {1} come in a season.": "{0} dias numa temporada garantem um achado, e no máximo {1} vêm por temporada.",
 "Its finds come only once the museum is yours, on long loan.": "Os achados dela só vêm quando o museu for seu, por empréstimo de longo prazo.",
 "The Museum tab's Dig card shows how the season is going.": "O quadro da escavação, na aba Museu, mostra como vai a temporada.",
 "A piece in parts (a skeleton) comes one part at a time, each shown under its tile.": "Uma peça em partes (um esqueleto) vem uma parte de cada vez, cada uma mostrada sob o cartão dela.",
 "Once every part is in, the workshop mounts it from the Museum tab, for a fee and a few days, and then it counts.": "Quando todas as partes chegam, a oficina a monta pela aba Museu, por uma taxa e alguns dias, e então ela conta.",
 "A dig": "Uma escavação",
 "Dig": "Escavação",
 "How likely among the dig's pieces (0 … 1; empty: 1, as likely as any)": "Probabilidade entre as peças da escavação (0 … 1; vazio: 1, tão provável quanto qualquer outra)",
 "Pick a dig.": "Escolha uma escavação.",
 "No dig called {0}.": "Nenhuma escavação chamada {0}.",
 "Its parts (a piece found part by part; optional)": "As partes dela (uma peça achada parte por parte; opcional)",
 "Parts (ids, separated by commas)": "Partes (ids, separados por vírgulas)",
 "Each part comes on its own from its ways (a dig); the slot fills once they are all in and, with a museum, mounted.": "Cada parte vem sozinha pelos caminhos dela (uma escavação); o espaço se preenche quando todas chegam e, com um museu, depois de montada.",
 "A picture per part": "Uma imagem por parte",
