 "(set by the pictures' wiring)": "(definida pela ligação das imagens)",
 "Mounted by the workshop once every part is in": "Montada pela oficina quando todas as partes chegarem",
 "Days it takes": "Dias que leva",
 "Add mounting by the workshop": "Adicionar montagem pela oficina",
 "Without mounting it fills the moment its last part comes.": "Sem montagem, ela se preenche assim que chega a última parte.",
 "{0}: a part's id is lowercase letters, digits and _ only (dropped when the world loads).": "{0}: o id de uma parte só tem letras minúsculas, dígitos e _ (descartado quando o mundo carrega).",
 "Its parts come from a dig: give it a way from one (A dig).": "As partes dela vêm de uma escavação: dê a ela um caminho por uma (Uma escavação).",
 "Mounting is for a piece of parts: without parts it is dropped when the world loads.": "A montagem é para uma peça em partes: sem partes, é descartada quando o mundo carrega.",
 "Mounting needs a price and days, or it is dropped when the world loads.": "A montagem precisa de um preço e de dias, ou é descartada quando o mundo carrega.",
 "The world has no museum: the piece fills the moment its last part comes, mounting is ignored.": "O mundo não tem museu: a peça se preenche assim que chega a última parte, e a montagem é ignorada.",
 "No upgrade of the museum is a workshop, so no one mounts it.": "Nenhuma melhoria do museu é uma oficina, então ninguém a monta.",
 "Digs": "Escavações",
 "No digs yet.": "Nenhuma escavação ainda.",
 "New dig": "Nova escavação",
 "A dig at one of the world's places: its things to do dig while its season holds, each season counted apart. A day dug rolls for one of the pieces whose way is this dig; some days in a season make sure of a find, and a season gives so many at most. A piece of parts (a fossil) comes part by part.": "Uma escavação num dos lugares do mundo: as coisas para fazer dela escavam enquanto a temporada dela vale, cada temporada contada à parte. Um dia de escavação sorteia uma das peças cujo caminho é esta escavação; alguns dias numa temporada garantem um achado, e uma temporada dá no máximo um tanto. Uma peça em partes (um fóssil) vem parte por parte.",
 "{0} pieces": "{0} peças",
 "lent": "emprestada",
 "The things to do that dig there": "As coisas para fazer que escavam lá",
 "This place has no things to do of its own yet (Things to do › Where).": "Este lugar ainda não tem coisas para fazer próprias (O que fazer › Onde).",
 "Its season (a condition; each time it holds again is a season of its own)": "A temporada dela (uma condição; cada vez que volta a valer é uma temporada nova)",
 "A day's odds of a find (0 … 1; optional)": "Chance de achado num dia (0 … 1; opcional)",
 "Days in a season that make sure of a find (optional)": "Dias numa temporada que garantem um achado (opcional)",
 "Finds in a season at most (optional)": "Achados no máximo por temporada (opcional)",
 "Its finds are lent to the museum": "Os achados dela são emprestados ao museu",
 "They come only to an open museum, on loan.": "Só vêm para um museu aberto, por empréstimo.",
 "Pieces from this dig · {0}": "Peças desta escavação · {0}",
 "None yet: a piece gets a way from it in its slot (Where the piece comes from › A dig).": "Nenhuma ainda: uma peça ganha um caminho por ela no espaço dela (De onde a peça vem › Uma escavação).",
 "No name: it shows as its id.": "Sem nome: aparece pelo id.",
 "Pick its place: without one the dig is dropped when the world loads.": "Escolha o lugar dela: sem um, a escavação é descartada quando o mundo carrega.",
 "It needs at least one thing to do that digs: without one it is dropped when the world loads.": "Precisa de pelo menos uma coisa para fazer que escave: sem uma, é descartada quando o mundo carrega.",
 "{0} isn't done at {1}.": "{0} não se faz em {1}.",
 "It needs a season (a condition): without one it is dropped when the world loads.": "Precisa de uma temporada (uma condição): sem uma, é descartada quando o mundo carrega.",
 "Days that make sure of a find ({0}) should be no more than the finds a season at most ({1}).": "Os dias que garantem um achado ({0}) não devem passar dos achados no máximo por temporada ({1}).",
 "Lent to a museum, but the world has none: its finds come straight to the collection.": "Emprestada a um museu, mas o mundo não tem nenhum: os achados vão direto para a coleção.",
 "Its finds come only once the museum is open: ask museum: open in its season or its things to do, or days dug before then find nothing.": "Os achados dela só vêm com o museu aberto: peça museum: open na temporada ou nas coisas para fazer dela, senão os dias escavados antes disso não acham nada.",
 "No piece comes from this dig yet (a piece's way: A dig).": "Nenhuma peça vem desta escavação ainda (o caminho de uma peça: Uma escavação).",
 "Mounting needs {0}": "A montagem precisa de {0}",
 "\"{0}\" has no key (write key: value)": "\"{0}\" não tem chave (escreva chave: valor)",
 "{0}'s royalties: +{1}": "Direitos autorais de {0}: +{1}",
 "{0}: royalties": "{0}: direitos autorais",
 "Royalties come from {0}% complete.": "Os direitos autorais começam a partir de {0}% completo.",
 "Last week's royalties: {0}": "Direitos autorais da semana passada: {0}",
 "Royalties pay on Mondays.": "Os direitos autorais pagam às segundas.",
 "{0} a week at {1}% · {2} at 100%": "{0} por semana com {1}% · {2} com 100%",
 "{0} a week at 100%": "{0} por semana com 100%",
 "At {0}%:": "Com {0}%:",
 "Royalties": "Direitos autorais",
 "Once the museum is yours and at least {0}% complete, its name earns royalties every Monday: more for every piece, the most at 100%, and they keep coming after. Lent pieces count. Renown and shows don't change them.": "Quando o museu é seu e está pelo menos {0}% completo, o nome dele rende direitos autorais toda segunda: mais a cada peça, o máximo com 100%, e eles continuam vindo depois. Peças emprestadas contam. O renome e as exposições não os mudam.",
 "Royalties: the museum's name on books, prints and television, paid each Monday": "Direitos autorais: o nome do museu em livros, gravuras e televisão, pagos toda segunda",
 "Add royalties": "Adicionar direitos autorais",
 "Once the museum is yours, each Monday it earns by its percentage (the display halls, not a record): nothing below the first point, a straight line between two points, the last one's above it. Lent pieces count; renown and shows don't change it.": "Quando o museu é seu, toda segunda ele rende conforme a porcentagem dele (os salões de exposição, não um registro): nada abaixo do primeiro ponto, uma linha reta entre dois pontos, o valor do último acima dele. Peças emprestadas contam; o renome e as exposições não mudam isso.",
 "What a week pays ({0}) at a percentage": "O que uma semana paga ({0}) numa porcentagem",
 "At (%)": "Com (%)",
 "A week ({0})": "Por semana ({0})",
 "Add a point": "Adicionar um ponto",
 "Lines as it grows (said once, the first time the museum reaches the percentage)": "Falas conforme cresce (ditas uma vez, na primeira vez que o museu chega à porcentagem)",
 "The line (in the news)": "A fala (nas notícias)",
 "What the AI is told from then on": "O que a IA fica sabendo a partir daí",
 "Add a line": "Adicionar uma fala",
 "Royalties need a point that pays something: without one they are dropped when the world loads.": "Os direitos autorais precisam de um ponto que pague algo: sem ele, são descartados quando o mundo carrega.",
 "Royalty point {0} should be at a higher percentage than the one before it.": "O ponto {0} dos direitos autorais deveria estar numa porcentagem mais alta que o anterior.",
 "Royalty line {0} needs its words: without them it is dropped when the world loads.": "A fala {0} dos direitos autorais precisa de texto: sem ele, é descartada quando o mundo carrega.",
 "The museum's royalties": "Direitos autorais do museu",
 "All royalties": "Todos os direitos autorais",
