 "Keep it let": "Manter alugada",
 "Take it back…": "Retomar a casa…",
 "An agent finds a tenant most weeks and pays you on Mondays, less a share. You can let 3 homes at most; to have one back, give a week's notice.": "Uma imobiliária encontra inquilino na maioria das semanas e paga você às segundas, menos uma comissão. Você pode alugar no máximo 3 casas; para ter uma de volta, dê uma semana de aviso prévio.",
 "Buy to let": "Comprar para alugar",
 "Let it out…": "Pôr para alugar…",
 "Let it out": "Pôr para alugar",
 "A tenant about {0} of weeks pays {1} a week, less the agent's {2}; the upkeep, {3} a week, is yours either way: about {4} a week on average. The first tenant can come on Monday.": "Um inquilino em cerca de {0} das semanas paga {1} por semana, menos os {2} da imobiliária; a manutenção, {3} por semana, é sua de qualquer jeito: cerca de {4} por semana em média. O primeiro inquilino pode chegar na segunda.",
 "{0} stops being your second home. A tenant about {1} of weeks pays {2} a week, less the agent's {3}; the upkeep, {4} a week, is yours either way: about {5} a week on average. The first tenant can come on Monday.": "{0} deixa de ser sua segunda casa. Um inquilino em cerca de {1} das semanas paga {2} por semana, menos os {3} da imobiliária; a manutenção, {4} por semana, é sua de qualquer jeito: cerca de {5} por semana em média. O primeiro inquilino pode chegar na segunda.",
 "You own the home you live in now. Sell it, keep it as your second home, or let it?": "A casa em que você mora agora é sua. Vender, ficar com ela como segunda casa, ou pôr para alugar?",
 "You own the home you live in. Before moving to {0}: sell it, keep it as your second home, or let it?": "A casa em que você mora é sua. Antes de se mudar para {0}: vender, ficar com ela como segunda casa, ou pôr para alugar?",
 "Its tenant stays with the new owner.": "O inquilino fica com o novo dono.",
 "Take it back": "Retomar a casa",
 "A tenant lives at {0} this week. With a week's notice they leave on Monday, in {1} days, paying the rent to the end.": "Um inquilino mora em {0} esta semana. Com uma semana de aviso prévio, ele sai na segunda, em {1} dias, pagando o aluguel até o fim.",
 "Nobody lives at {0} this week: it's yours again at once.": "Ninguém mora em {0} esta semana: ela volta a ser sua na hora.",
 "Give notice": "Dar aviso prévio",
