 "A home you let can no longer be let in this world.": "Uma casa que você alugava não pode mais ser alugada neste mundo.",
 "{0} A home you let can no longer be let in this world.": "{0} Uma casa que você alugava não pode mais ser alugada neste mundo.",
 "The tenant at {0} has left: it's yours to move into, let again or sell.": "O inquilino de {0} saiu: ela é sua para morar, alugar de novo ou vender.",
 "Your homes to let, last week: {0} of {1} had a tenant, {2} after the agent's {3}.": "Suas casas para alugar, semana passada: {0} de {1} tiveram inquilino, {2} depois dos {3} da imobiliária.",
 "None of your homes to let had a tenant last week.": "Nenhuma das suas casas para alugar teve inquilino semana passada.",
 "Rent from your tenants, less the agent's share": "Aluguel dos seus inquilinos, menos a comissão da imobiliária",
