 "a home let": "uma casa alugada",
 "{0} homes let": "{0} casas alugadas",
 "{0} of rent from your tenants": "{0} de aluguel dos seus inquilinos",
 "Rent from your tenants": "Aluguel dos seus inquilinos",
 "Rent from your tenants +{0}": "Aluguel dos seus inquilinos +{0}",
 "Rent from your tenants −{0}": "Aluguel dos seus inquilinos −{0}",
 "Every home you let": "Toda casa que você aluga",
 "Homes at {0}": "Casas em {0}",
 "Homes here you own can be let": "Casas suas aqui podem ser alugadas",
 "An agent finds a tenant most weeks and pays you the rent less a share; the upkeep is still yours. Three homes let at most.": "Uma imobiliária encontra inquilino na maioria das semanas e paga a você o aluguel menos uma comissão; a manutenção continua sua. No máximo três casas alugadas.",
 "Rent when let, a week ({0}; empty: the rent here)": "Aluguel quando alugada, por semana ({0}; vazio: o aluguel daqui)",
 "A tenant most weeks (0.1–1; empty: 0.75)": "Chance de ter inquilino a cada semana (0.1–1; vazio: 0.75)",
 "The agent's share of the rent (0–0.5; empty: 0.2)": "A comissão da imobiliária sobre o aluguel (0–0.5; vazio: 0.2)",
 "Only a home for sale can be let: give it a price.": "Só uma casa à venda pode ser alugada: dê um preço a ela.",
 "A home to let needs a rent: the rent here, or a rent when let.": "Uma casa para alugar precisa de um aluguel: o aluguel daqui, ou um aluguel quando alugada.",
 "Letting": "Pôr para alugar",
 "Some homes you own can be let: buy one to let, let your second home, or let the one you live in when you move out. An agent finds a tenant most weeks and pays you every Monday, less a share; the upkeep is still yours, let or not. You can let 3 homes at most.": "Algumas casas suas podem ser alugadas: compre uma para alugar, ponha sua segunda casa para alugar, ou aquela em que você mora quando se mudar. Uma imobiliária encontra inquilino na maioria das semanas e paga você toda segunda, menos uma comissão; a manutenção continua sua, alugada ou não. Você pode alugar no máximo 3 casas.",
 "Taking a home back": "Retomar uma casa",
 "While a tenant is in, taking a home back needs a week's notice: they leave on a Monday and pay to the end. A home with nobody in that week is yours again at once. An empty home you own can be let again, lived in, made your second home or sold; a home that's let can be sold with its tenant.": "Com um inquilino morando, retomar uma casa exige uma semana de aviso prévio: ele sai numa segunda e paga até o fim. Uma casa sem ninguém naquela semana volta a ser sua na hora. Uma casa sua vazia pode ser alugada de novo, virar sua moradia, sua segunda casa ou ser vendida; uma casa alugada pode ser vendida com o inquilino.",
 "Your homes to let, last week: 1 of {0} had a tenant, {1} after the agent's {2}.": "Suas casas para alugar, semana passada: 1 de {0} teve inquilino, {1} depois dos {2} da imobiliária.",
