 "Homes for sale are in the {0} app: Buy, then live in it or keep it as a second home.": "As casas à venda estão no app {0}: Comprar, e depois morar nela ou mantê-la como segunda casa.",
 "Rooms and fixtures are bought for a home you own, in the {0} app's Rooms tab.": "Cômodos e comodidades se compram para uma casa sua, na aba Cômodos do app {0}.",
 "Let a home you own from the {0} app (Buy to let, or Let it out): an agent finds the tenants.": "Alugue uma casa sua pelo app {0} (Comprar para alugar, ou Pôr para alugar): uma imobiliária encontra os inquilinos.",
 "Things are bought in the {0} app, or at the shops that sell them.": "As coisas se compram no app {0}, ou nas lojas que as vendem.",
 "Your businesses, their tiers and discoveries are in the {0} app.": "Seus negócios, seus níveis e descobertas estão no app {0}.",
 "The record fills by itself as you live: see how far it is in the {0} app.": "O registro se preenche sozinho enquanto você vive: veja quanto falta no app {0}.",
 "The end game": "O fim de jogo",
 "Some goals wait for the late game: a home of your own and its rooms, homes to let, a café or hotels at their top, the executive floor, the museum's halls, the record. Their perks make a number grow (takings, rent, renown, finds), never a price come down. Late-game milestones give life points too (a hall complete, the record by quarters, your first home, a business at its top), inside the {0} a day: what doesn't fit comes the next morning.": "Algumas metas esperam o fim do jogo: uma casa sua e seus cômodos, casas para alugar, um café ou hotéis no topo, o andar executivo, os salões do museu, o registro. Suas vantagens fazem um número crescer (faturamento, aluguel, renome, achados), nunca um preço cair. Os marcos do fim de jogo também dão pontos de conquista (um salão completo, o registro por quartos, sua primeira casa, um negócio no topo), dentro dos {0} por dia: o que não couber vem na manhã seguinte.",
