 "There is no such room here.": "Não há esse cômodo aqui.",
 "You knock on {0}'s door. No answer: they're asleep.": "Você bate na porta de {0}. Ninguém responde: está dormindo.",
 "Rooms inside · {0}": "Cômodos · {0}",
 "This area's own rooms: when it has any, they replace the kind of home's.": "Os cômodos próprios desta área: quando ela tem algum, eles substituem os do tipo de casa.",
 "Every home of this kind has them, unless its area has its own.": "Toda casa deste tipo os tem, a não ser que a área tenha os seus.",
 "The first is where you come in. Walking between them takes no time and keeps the scene; everyone who lives there also gets a bedroom of their own.": "O primeiro é por onde você entra. Andar entre eles não leva tempo e mantém a cena; cada pessoa que mora lá também ganha um quarto próprio.",
