 "They are already staying with you.": "A pessoa já está hospedada com você.",
 "They are not close enough to you to stay at your place.": "Vocês não são próximos o bastante para a pessoa ficar na sua casa.",
 "{0} is already staying with you.": "{0} já está hospedado(a) com você.",
 "They cannot stay with you.": "A pessoa não pode ficar com você.",
 "Staying over": "Hospedar alguém",
 "A close friend or your partner can stay at your place for a few nights, or until you say goodbye (a week at most): Ask to stay a few days, in the menu when you click them in the scene. They ring the doorbell, go out to work from your place, and grow a little closer each night.": "Um amigo próximo ou seu par pode ficar na sua casa por algumas noites, ou até você se despedir (uma semana no máximo): Convidar para ficar uns dias, no menu ao clicar na pessoa na cena. Ela toca a campainha, sai para trabalhar da sua casa e fica um pouco mais próxima a cada noite.",
 "On · only friends come to find you, and rarely": "Ligado · só amigos vêm te procurar, e raramente",
 "Off · housemates may come to find you": "Desligado · os moradores podem vir te procurar",
 "Some homes have rooms inside (a share house: the common room, the kitchen, the bathroom, a bedroom each). Walking between them takes no time; the scene is the room you are in, and \"Elsewhere at home\" shows who is in the others. Housemates keep the house's rhythm and come to find you now and then (Keep to myself keeps all but friends away). Someone's bedroom is theirs: close friends walk in, others knock.": "Algumas casas têm cômodos (uma casa compartilhada: a sala comum, a cozinha, o banheiro, um quarto para cada um). Andar entre eles não leva tempo; a cena é o cômodo onde você está, e \"Em outro lugar da casa\" mostra quem está nos outros. Os moradores seguem o ritmo da casa e de vez em quando vêm te procurar (Ficar na minha afasta todos, menos os amigos). O quarto de alguém é dele: amigos próximos entram, os outros batem.",
 "Outfits for the place": "Roupa para o lugar",
 "nobody changes into swimwear or other outfits for a place or an activity (with adult content on, private moments still undress).": "ninguém põe roupa de banho ou outra roupa por causa de um lugar ou de uma atividade (com conteúdo adulto ligado, nos momentos privados as pessoas ainda tiram a roupa).",
 "What people wear (dress code)": "O que as pessoas vestem (código de vestimenta)",
 "Kind of outfit (empty: none)": "Tipo de roupa (vazio: nenhum)",
 "Whoever has outfits of this kind puts one on, as bold as they go here: swim, yukata…": "Quem tem roupas deste tipo veste uma, tão ousada quanto se permite aqui: swim, yukata…",
 "While (optional)": "Enquanto (opcional)",
 "Scripted level (1–4; empty: each as bold as they go)": "Nível fixo (1–4; vazio: cada um tão ousado quanto se permite)",
 "Only for (names; empty: everyone it covers)": "Só para (nomes; vazio: todos que ele abrange)",
 "The level is for them; the others as bold as they go.": "O nível é para eles; os outros, tão ousados quanto se permitem.",
 "The people doing it with you put it on while it plays out; in a private moment, instead of undressing.": "As pessoas que fazem isso com você vestem enquanto acontece; num momento privado, em vez de tirar a roupa.",
 "The people it names (the one it brings, those it needs present) put it on while it goes on.": "As pessoas que ela nomeia (quem ela traz, quem precisa estar presente) vestem enquanto dura.",
 "Everyone here puts it on while it holds (a pool in summer).": "Todos aqui vestem enquanto valer (uma piscina no verão).",
 "What their outfits are · {0}": "O que são suas roupas · {0}",
 "An outfit with a kind can be put on by a dress code (a pool, a swim, a festival), the boldest they go there; one with a kind uploads the first time it's worn.": "Uma roupa com tipo pode ser vestida por um código de vestimenta (uma piscina, um mergulho, um festival), a mais ousada que a pessoa se permite ali; uma roupa com tipo é enviada na primeira vez que é usada.",
 "How bold they go in public (1–3; one more in private with someone close; empty: 2)": "Quão ousado se permite em público (1–3; um a mais em particular com alguém próximo; vazio: 2)",
 "Kind (empty: none)": "Tipo (vazio: nenhum)",
 "How bold (1 modest, 2 everyday, 3 bold, 4 explicit)": "Quão ousada (1 discreta, 2 do dia a dia, 3 ousada, 4 explícita)",
 "What it is, for the AI": "O que é, para a IA",
 "Explicit ones (4) always are.": "As explícitas (4) sempre são.",
 "Dressing for the place": "Roupa para o lugar",
 "At a pool, on a beach in summer or for a swim, people change into swimwear, each as bold as they go in public, a little bolder in private with someone close. What they wear is theirs to choose, not yours. The AI is told what everyone wears.": "Numa piscina, numa praia no verão ou para nadar, as pessoas põem roupa de banho, cada uma tão ousada quanto se permite em público, um pouco mais em particular com alguém próximo. O que cada um veste, cada um escolhe; não você. A IA fica sabendo o que cada um veste.",
 "Its folder of sprites (empty: waiting for its pictures)": "A pasta de sprites dela (vazio: esperando as imagens)",
 "Closed all through": "Fechado durante todo o",
 "Everyone at its places puts it on during its days (yukata at a summer festival).": "Todos nos lugares dele vestem nos dias dele (yukata num festival de verão).",
 "They put it on while they're at it (her fencing whites at the club).": "Vestem enquanto estão nele (o uniforme branco de esgrima dela no clube).",
