 "Its rent is a week overdue: pay it to work there again.": "O aluguel está uma semana atrasado: pague para voltar a trabalhar lá.",
 "The upkeep is a week overdue: the studio's fixtures are off and you can't work there until it's paid.": "A manutenção está uma semana atrasada: as comodidades do estúdio estão desligadas e você não pode trabalhar lá até pagar.",
