 "{0}/wk": "{0}/sem",
 "A place to work, never to live in: it isn't one of your homes. One studio at a time: taking another gives up the one you have. Rented, it's a weekly rent; bought, a weekly upkeep, and sold back it returns part of what you paid (its fixtures stay with it).": "Um lugar para trabalhar, nunca para morar: não é uma das suas casas. Um estúdio de cada vez: pegar outro faz você largar o que tem. Alugado, é um aluguel semanal; comprado, uma manutenção semanal, e revendido ele devolve parte do que você pagou (as comodidades ficam com ele).",
 "Rent a photo studio": "Alugar um estúdio fotográfico",
 "Buy a photo studio": "Comprar um estúdio fotográfico",
 "{0}: {1} a week, the first week paid now; the Studio rent bill comes every week after.": "{0}: {1} por semana, a primeira semana paga agora; depois a conta Aluguel do estúdio vem toda semana.",
 "{0}: {1}, then {2} a week of upkeep on the Home upkeep bill. Sold back, it returns {3} of what you paid.": "{0}: {1}, depois {2} por semana de manutenção na conta Manutenção da casa. Revendido, devolve {3} do que você pagou.",
 "You rent {0} now: its rent ends.": "Agora você aluga {0}: esse aluguel termina.",
 "{0} was given to you: given up, it's gone for good.": "{0} foi um presente: se você largar, perde de vez.",
 "{0} is sold for {1}.": "{0} é vendido por {1}.",
 "The studio you rent becomes yours: its rent ends.": "O estúdio que você aluga passa a ser seu: o aluguel termina.",
 "Rent for {0}": "Alugar por {0}",
 "Give up your photo studio": "Largar seu estúdio fotográfico",
 "The rent of {0} ends today; what's owed, {1}, is paid first. Its fixtures stay with the studio.": "O aluguel de {0} termina hoje; o que se deve, {1}, é pago antes. As comodidades ficam com o estúdio.",
 "The rent of {0} ends today. Its fixtures stay with the studio.": "O aluguel de {0} termina hoje. As comodidades ficam com o estúdio.",
 "{0} was given to you: given up, it's gone for good, with its fixtures.": "{0} foi um presente: se você largar, perde de vez, com as comodidades.",
 "{0} sells for {1} ({2} of the {3} you paid). Its fixtures go with it; what's owed on the upkeep is paid from the sale.": "{0} é vendido por {1} ({2} dos {3} que você pagou). As comodidades vão junto; o que se deve de manutenção sai da venda.",
