 "That studio isn't for sale.": "Esse estúdio não está à venda.",
 "You don't have a photo studio.": "Você não tem um estúdio fotográfico.",
 "Pay what's owed on the studio's rent first ({0}).": "Pague primeiro o que deve do aluguel do estúdio ({0}).",
 "{0}: its rent has ended.": "{0}: o aluguel terminou.",
 "{0}: sold for {1}.": "{0}: vendido por {1}.",
