 "You gave up your photo studio, {0}": "Você largou seu estúdio fotográfico, {0}",
 "{0} is your photo studio now (see the Homes app).": "{0} agora é o seu estúdio fotográfico (veja o app Moradia).",
 "{0} can't be rented any more: its rent has ended.": "{0} não pode mais ser alugado: o aluguel terminou.",
 "A photo studio you had is gone from this world: what you paid for it was paid back.": "Um estúdio fotográfico que você tinha não existe mais neste mundo: o que você pagou foi devolvido.",
 "A photo studio you had is gone from this world.": "Um estúdio fotográfico que você tinha não existe mais neste mundo.",
 "A fixture of your photo studio is gone from this world.": "Uma comodidade do seu estúdio fotográfico não existe mais neste mundo.",
 "{0} fixtures of your photo studio are gone from this world.": "{0} comodidades do seu estúdio fotográfico não existem mais neste mundo.",
 "{0}: the first week's rent": "{0}: aluguel da primeira semana",
 "{0}: rent owed": "{0}: aluguel devido",
 "A photo studio the world no longer has, paid back": "Um estúdio fotográfico que o mundo não tem mais, devolvido",
 "Studio rent": "Aluguel do estúdio",
 "The rent of your photo studio is a week overdue: you can't work there, and its fixtures are off, until it's paid (in the Homes app).": "O aluguel do seu estúdio fotográfico está uma semana atrasado: você não pode trabalhar lá, e as comodidades ficam desligadas, até pagar (no app Moradia).",
 "Studio rent paid: your photo studio is yours to work in again.": "Aluguel do estúdio pago: seu estúdio fotográfico está de novo à sua disposição.",
 "My photo studio": "Meu estúdio fotográfico",
 "Studio rental": "Aluguel de estúdio",
 "Rent the studio (2 h)": "Alugar o estúdio (2 h)",
 "Rent the studio 2 more hours": "Alugar o estúdio por mais 2 horas",
 "The studio is yours until {0}.": "O estúdio é seu até as {0}.",
 "{0} and {1} set a date: they marry on {2}, in {3} days.": "{0} e {1} marcaram a data: vão se casar daqui a {3} dias ({2}).",
 "Photography": "Fotografia",
 "no Lens app, no photo gigs or reputation, no photobooks (taking photos and the skill stay).": "sem app Lente, sem trabalhos de fotografia nem reputação, sem fotolivros (tirar fotos e a habilidade continuam).",
 "Clients": "Clientes",
 "Photo studios": "Estúdios fotográficos",
 "Photo gear": "Equipamento fotográfico",
 "Pay and reputation": "Pagamento e reputação",
 "What it asks": "O que pede",
 "Who is in front of the camera": "Quem fica na frente da câmera",
 "No photo gigs in this world: no Lens app, no boards of briefs, no photobooks. Taking photos and the photography skill still play.": "Nenhum trabalho de fotografia neste mundo: sem app Lente, sem murais de pautas, sem fotolivros. Tirar fotos e a habilidade de fotografia continuam valendo.",
 "Add photo gigs to this world": "Adicionar trabalhos de fotografia a este mundo",
 "Remove the photo gigs": "Remover os trabalhos de fotografia",
 "Anyone with a camera gets the small board of photo gigs in the Lens app; the job's studio ranks and its freelance paths get the full board. Briefs are shot, edited and delivered for stars, pay and reputation; a photographer with a name is offered photobooks.": "Quem tem uma câmera ganha o mural pequeno de bicos no app Lente; os cargos de estúdio do emprego e seus caminhos freelancer ganham o mural completo. As pautas são fotografadas, editadas e entregues por estrelas, pagamento e reputação; a quem tem nome são oferecidos fotolivros.",
 "The Photography system is off in this world (Features): none of this plays.": "O sistema Fotografia está desligado neste mundo (Recursos): nada disso vale.",
 "Who the briefs are for: magazines, wedding planners, events, small jobs. A client offers nothing below its reputation; a contact keeps calling after you quit the job.": "Para quem são as pautas: revistas, cerimonialistas, eventos, bicos. Um cliente não oferece nada abaixo da reputação que pede; um contato continua chamando depois que você sai do emprego.",
 "The jobs on the boards, as each client writes them: where and when they can be shot, what they pay, what they ask, and who is in front of the camera.": "Os trabalhos dos murais, como cada cliente os escreve: onde e quando podem ser fotografados, quanto pagam, o que pedem e quem fica na frente da câmera.",
 "What a publisher can offer a photographer with a name: a book of the city, a person or a season, shot brief by brief, then paying royalties that fade.": "O que uma editora pode oferecer a quem tem nome na fotografia: um livro da cidade, de uma pessoa ou de uma estação, fotografado pauta a pauta, que depois paga direitos autorais que vão diminuindo.",
 "A studio the player can rent by the week or buy, one at a time, in the Homes app: a place of its own to shoot and edit in, with fixtures bought for it. Never lived in, let or anybody's home; housing areas never list it.": "Um estúdio que o jogador pode alugar por semana ou comprar, um de cada vez, no app Moradia: um lugar próprio para fotografar e editar, com comodidades compradas para ele. Ninguém mora nele, não é alugado a inquilinos nem é casa de ninguém; as áreas de moradia nunca o listam.",
 "Read by the photo gigs themselves, so a shoot's result names what added to it.": "Lido pelos próprios trabalhos de fotografia, para que o resultado de uma sessão diga o que contribuiu para ele.",
 "The deadline counts from the day it's offered; a window whose weather is rare in the season gets more days, and the client one extension when it never came.": "O prazo conta a partir do dia em que é oferecida; uma janela cujo tempo é raro na estação ganha mais dias, e o cliente dá uma prorrogação quando ele não veio.",
 "Three times as often there; the other paths see it too.": "Três vezes mais frequente ali; os outros caminhos também a veem.",
 "Nobody: a place, a dish, the city.": "Ninguém: um lugar, um prato, a cidade.",
 "Besides every keepsake of the kind photo.": "Além de toda lembrança do tipo foto.",
 "The first open on the day; none: no wedding offers.": "O primeiro aberto no dia; nenhum: sem ofertas de casamento.",
 "None: the game's own (unknown, getting noticed, in demand, a name).": "Nenhuma: as do jogo (desconhecido, começando a ser notado, requisitado, um nome).",
 "None: the same picture at every hour (a basement has no windows).": "Nenhuma: a mesma imagem a qualquer hora (um porão não tem janelas).",
 "Besides what its kind comes with.": "Além do que o tipo dele já traz.",
 "Not a place of this world (dropped when it loads)": "Não é um lugar deste mundo (descartado ao carregar)",
 "Publishes the photobooks": "Publica os fotolivros",
