 "Yes as a friend, half the time as an acquaintance; otherwise the offer goes.": "Sim como amigo, metade das vezes como conhecido; senão a oferta some.",
 "The scene, for the AI": "A cena, para a IA",
 "the cover model on a white cyclorama, one light, the editor at the monitor": "the cover model on a white cyclorama, one light, the editor at the monitor",
 "No such client: it is dropped when the world loads.": "Esse cliente não existe: é descartado quando o mundo carrega.",
