 "A brief that needs a studio is shot at Any photo studio: pick it among the places.": "Uma pauta que precisa de estúdio é fotografada em Qualquer estúdio fotográfico: escolha-o entre os lugares.",
 "No such photobook: its part in one is dropped when the world loads.": "Esse fotolivro não existe: a participação nele é descartada quando o mundo carrega.",
 "Gear of a kind the game doesn't know.": "Equipamento de um tipo que o jogo não conhece.",
 "{0}'s rule in front of a camera rules this brief out: it is dropped when the world loads.": "A regra de {0} diante de uma câmera exclui esta pauta: ela é descartada quando o mundo carrega.",
 "Nobody of the world has that name: it is never offered.": "Ninguém do mundo tem esse nome: nunca é oferecida.",
