 "{0} briefs": "{0} pautas",
 "Briefs to shoot (1–8)": "Pautas a fotografar (1–8)",
 "Weeks its royalties fade over (1–520; empty: two seasons)": "Semanas em que os direitos autorais diminuem (1–520; vazio: duas estações)",
 "Weekly royalties at the start (by how good its photos were; held to 5,000–20,000)": "Direitos autorais semanais no início (pela qualidade das fotos; entre 5.000 e 20.000)",
