 // a person's door and getting caught with them (sim/homerooms.ts, sim/caught.ts, core/lexicon.ts, ui/creator.ts)
 "You leave at once.": "Você sai na hora.",
 "Someone saw or heard you.": "Alguém viu ou ouviu vocês.",
 "It's a home: nobody asks you to leave.": "É uma casa: ninguém pede para você sair.",
 "You ring the doorbell. {0} comes to the door but doesn't ask you in: nobody comes into {0}'s home.": "Você toca a campainha. {0} vem até a porta, mas não convida você a entrar: ninguém entra na casa de {0}.",
 "You knock. {0} comes to the door but doesn't ask you in: nobody comes into {0}'s home.": "Você bate. {0} vem até a porta, mas não convida você a entrar: ninguém entra na casa de {0}.",
 "Their door": "A porta da pessoa",
 "Who comes into their home, asked before how close the player is. It closes their bedroom in a home with rooms, staying the night at theirs and their \"come over tonight?\" too, adult content on or off (unless it holds only with adult content on).": "Quem entra na casa da pessoa, perguntado antes de ver o quanto o jogador é próximo. Também fecha o quarto dela numa casa com cômodos, dormir na casa dela e o \"vem pra cá hoje?\" dela, com conteúdo adulto ligado ou desligado (a menos que só valha com conteúdo adulto ligado).",
 "With adult content off they let the player in as usual, as if they had no rule (for a door an adult storyline opens).": "Com conteúdo adulto desligado, a pessoa deixa o jogador entrar como de costume, como se não tivesse regra (para uma porta que uma história adulta abre).",
 "Who they let in": "Quem ela deixa entrar",
 "As usual (friends come in, close friends know where the key is)": "Como de costume (amigos entram, amigos próximos sabem onde está a chave)",
 "Nobody, ever (not even a partner)": "Ninguém, nunca (nem um parceiro)",
 "Only once a condition holds": "Só depois que uma condição valer",
 "Their door opens once (a condition)": "A porta se abre quando (uma condição)",
 "What the player is told at their closed door ({name}: their name; empty: the world's words)": "O que o jogador ouve na porta fechada ({name}: o nome da pessoa; vazio: as palavras do mundo)",
 "{name} meets you downstairs: nobody comes up to {name}'s flat.": "{name} encontra você lá embaixo: ninguém sobe até o apartamento de {name}.",
 "Getting caught with them": "Ser pego com a pessoa",
 "When a risky private moment with them is seen: one row that fits where it happens is drawn by weight instead of the plain line. At a home nobody bans you (word gets around from the people who live there); anywhere else the place still won't serve you for a week.": "Quando um momento íntimo arriscado com a pessoa é visto: uma linha que combine com o lugar é sorteada pelo peso no lugar da frase simples. Numa casa ninguém proíbe sua entrada (a notícia se espalha a partir de quem mora lá); em qualquer outro lugar, o lugar continua sem atender você por uma semana.",
 "Anywhere with them": "Em qualquer lugar com a pessoa",
 "At their home (shared or not)": "Na casa da pessoa (dividida ou não)",
 "At your home": "Na sua casa",
 "Any home in {0}": "Qualquer casa em {0}",
 "Any place tagged {0}": "Qualquer lugar com a etiqueta {0}",
 "Who saw, and how they take it ({{user}}: you)": "Quem viu, e como a pessoa reage ({{user}}: você)",
 "Weight (how often, against their other rows)": "Peso (com que frequência, contra as outras linhas da pessoa)",
 "The rumor in its own words ({u}: you; empty: who and where)": "O boato com as próprias palavras ({u}: você; vazio: quem e onde)",
 "Their friendship toward you after it (−20–20)": "A amizade dela por você depois disso (−20–20)",
 "Their romance toward you after it (−20–20)": "O romance dela por você depois disso (−20–20)",
 "Doing": "Fazendo",
 "Any risky action": "Qualquer ação arriscada",
 "Add a way of getting caught": "Adicionar um jeito de ser pego",
 "Its own background": "Fundo próprio",
 "While it plays, the scene shows this instead of the place's or the room's picture, until the scene moves on.": "Enquanto acontece, a cena mostra esta imagem em vez da do lugar ou do cômodo, até a cena seguir adiante.",
 "Picture (a file in the world's folder or a /user/files/ address; empty: the place's)": "Imagem (um arquivo na pasta do mundo ou um endereço /user/files/; vazio: a do lugar)",
 "Picture (a file in the world's folder or a /user/files/ address; empty: the icon)": "Imagem (um arquivo na pasta do mundo ou um endereço /user/files/; vazio: o ícone)",
 "A picture by place (shown there instead of the ones above)": "Uma imagem por lugar (mostrada lá em vez das de cima)",
