 "everyone answers your messages at once, even at work or asleep.": "todos respondem suas mensagens na hora, mesmo no trabalho ou dormindo.",
 "Delivered. They're probably asleep: they'll answer in the morning.": "Entregue. A pessoa deve estar dormindo: vai responder de manhã.",
 "Delivered. They're probably at work: they'll answer when they get a moment.": "Entregue. A pessoa deve estar no trabalho: vai responder quando tiver um tempinho.",
