 "Asking by text": "Convidar por mensagem",
 "Write \"dinner tomorrow at 8?\" and it is an invitation: they say yes or no as they would to Make plans, and a yes is in the calendar.": "Escreva \"jantar amanhã às 8?\" e vira um convite: a pessoa diz sim ou não como diria em Fazer planos, e um sim vai para o calendário.",
 "Someone at work answers when they get a moment, someone asleep in the morning; your message shows as delivered until then.": "Quem está no trabalho responde quando tiver um tempinho, quem está dormindo de manhã; até lá sua mensagem aparece como entregue.",
 "Everyone you know, with their bars and what they feel. A person's page has About (where they are, their work and week), Memories, Circle (the people in their life) and Notes (yours, and the gifts you gave).": "Todo mundo que você conhece, com as barras e o que sentem. A página de uma pessoa tem Sobre (onde está, o trabalho e a semana), Memórias, Círculo (as pessoas da vida dela) e Notas (as suas, e os presentes que você deu).",
 "Unfold": "Desdobrar",
 "The button next to ✕ makes the phone twice as wide: Messages and People show the list and what it opens side by side. Back goes one step back; the bar at the bottom goes home.": "O botão ao lado do ✕ deixa o celular duas vezes mais largo: Mensagens e Pessoas mostram a lista e o que ela abre lado a lado. Voltar volta um passo; a barra embaixo vai para a tela inicial.",
 "Notices": "Avisos",
 "No news yet.": "Nenhuma notícia ainda.",
 "Nothing pinned on the board yet.": "Nada pregado no quadro ainda.",
 "At the top of Messages: what is on in town, what happened in the lives of the people you know, and what they post. Tap someone to open their page.": "No alto de Mensagens: o que acontece na cidade, o que houve na vida das pessoas que você conhece e o que elas postam. Toque em alguém para abrir a página da pessoa.",
 "At the top of your letters: what is on in town, the news of the people you know, and the notices they pin on the board.": "No alto das suas cartas: o que acontece na cidade, as notícias das pessoas que você conhece e os avisos que elas pregam no quadro.",
