 "What they put up, in their own words: no surname, job or age (the app shows the age). In a world with a matchmaker, the matchmaker's word about them. Empty: the AI writes one the first time they're shown.": "O que a pessoa publica, com as próprias palavras: sem sobrenome, profissão ou idade (o app mostra a idade). Num mundo com casamenteira, o que a casamenteira diz dela. Vazio: a IA escreve um na primeira vez que aparecer.",
