 "A little revealing": "Um pouco reveladora",
 "Revealing": "Reveladora",
 "How bold they go, and how bold their outfits are, comes from their world.": "O quanto a pessoa ousa, e o quanto as roupas dela são ousadas, vem do mundo dela.",
 "A room's dress code at Home is followed only this far: anyone it asks for a bolder outfit keeps their own clothes (one level more in private with someone close; never explicit).": "O código de vestimenta de um cômodo em Home só é seguido até aqui: quem receberia uma roupa mais ousada continua com a própria roupa (um nível a mais em particular com alguém próximo; nunca explícito).",
 "Switch to another person of the world from your photo or your household. Each person keeps their own relationships, diary and job.": "Troque para outra pessoa do mundo pela sua foto ou pelos rostos da sua casa. Cada pessoa mantém as próprias relações, diário e emprego.",
 "Your name, money, energy and needs. Click your photo to use another SillyTavern persona.": "Seu nome, dinheiro, energia e necessidades. Clique na sua foto para usar outra persona do SillyTavern.",
 "The faces under your card. Click one to call them over or go to them.": "Os rostos embaixo do seu card. Clique num para chamá-lo ou ir até ele.",
 "You don't know them yet.": "Você ainda não conhece essa pessoa.",
 "You don't know what they do yet.": "Você ainda não sabe o que essa pessoa faz.",
 "My page in People. Friendship and romance bars fill up as we hang out. Plans, messages, what you know about me: it's all here.": "Minha página em Pessoas. As barras de amizade e romance enchem conforme a gente sai junto. Planos, mensagens, o que você sabe de mim: tá tudo aqui.",
 "Click me in the scene for what we can do right now: come along with you, make plans, talk just to me.": "Clique em mim na cena para ver o que dá para fazer agora: ir junto com você, fazer planos, falar só comigo.",
 "Click your photo to switch personas. Turn on Play as in Settings and you can be anyone in your world. Wild, right?": "Clique na sua foto para trocar de persona. Ligue Jogar como nas Configurações e você pode ser qualquer pessoa do seu mundo. Doido, né?",
 "Outfits": "Roupas",
 "Outfits follow the story": "As roupas acompanham a história",
 "When a reply clearly has someone undress, dress again or change clothes, their picture follows and the AI is told. Undressing only in a private place with adult content on; changing into another outfit only where they can change (their home). One short AI call after a reply, only when someone in it could change. Off: only places, things to do and private moments change what people wear.": "Quando uma resposta mostra claramente alguém se despindo, se vestindo de novo ou trocando de roupa, a imagem acompanha e a IA fica sabendo. Despir-se só num lugar privado com conteúdo adulto ativado; trocar por outra roupa só onde dá para se trocar (a casa da pessoa). Uma chamada curta à IA depois de uma resposta, só quando alguém nela poderia se trocar. Desativado: só lugares, coisas para fazer e momentos íntimos mudam o que as pessoas vestem.",
 "Opens from (the story)": "Se abre a partir de (a história)",
 "The outfits this one is a state of, comma-separated (\"own\" for their own clothes): when the story has them open or take something off, it can go from those into this one, and back. In private; in public too when it isn't adult and stays within how bold they go there. A half-undressed outfit (kind \"undressed\") with nothing here opens from their own clothes.": "As roupas das quais esta é um estado, separadas por vírgulas (\"own\" para as roupas da própria pessoa): quando a história faz a pessoa abrir ou tirar algo, ela pode passar daquelas para esta, e voltar. Em particular; em público também quando não é adulta e fica dentro do quanto a pessoa ousa ali. Uma roupa meio despida (tipo \"undressed\") sem nada aqui se abre a partir das roupas da própria pessoa.",
 "Missing only": "Só o que falta",
 "Every one is filled.": "Todos estão preenchidos.",
 "The keepsakes": "As lembranças",
 "{0} of {1} held at some time": "{0} de {1} já tidas alguma vez",
 "Yours now: {0}": "Suas agora: {0}",
 "Had": "Já teve",
 "No known way to get it yet.": "Ainda não se sabe como conseguir.",
 "{0} of {1} been to": "{0} de {1} visitados",
 "{0} seen": "{0} vistas",
 "1 to find": "1 a encontrar",
 "{0} to find": "{0} a encontrar",
 "None left to find.": "Não falta nenhuma.",
 "How": "Como",
 "Finding what's missing": "Encontrar o que falta",
 "Tap a slot to open its page. A keepsake kind lists its keepsakes, the missing first, each with where it comes from; a district lists its places and where its street stories still wait; a festival or an event says when it's next. Missing only hides what you've already filled.": "Toque num espaço para abrir a página dele. Um tipo de lembrança lista as suas lembranças, as que faltam primeiro, cada uma com de onde vem; um bairro lista os seus lugares e onde as histórias de rua ainda esperam; um festival ou um evento diz quando é o próximo. Só o que falta esconde o que você já preencheu.",
 "Hide finished": "Ocultar concluídas",
 "Every goal here is finished.": "Todas as metas daqui estão concluídas.",
 "Nothing to suggest now.": "Nada a sugerir agora.",
 "{0} of {1} finished": "{0} de {1} concluídas",
 "Hide owned": "Ocultar o que já tem",
 "Search the shop": "Buscar na loja",
