 // the adult industry (ui/takeui.ts, ui/phone.ts, ui/business.ts, ui/help.ts, ui/creator.ts, sim/titles.ts, sim/bookings.ts, sim/onset.ts, sim/fame.ts, sim/stance.ts, sim/label.ts, sim/when.ts…)
 "Industry": "Indústria",
 "The adult industry": "A indústria adulta",
 "Genres · {0}": "Gêneros · {0}",
