 "The roster · {0}": "O elenco · {0}",
 "Scene pictures": "Imagens das cenas",
 "No adult industry in this world: no Take app, no bookings, titles, fame or stances; a job in adult video is worked in shifts like any other.": "Sem indústria adulta neste mundo: sem o app Take, sem propostas, títulos, fama ou posições; um emprego em vídeo adulto é feito em turnos como qualquer outro.",
 "Add the adult industry": "Adicionar a indústria adulta",
 "Add a job first: the industry books one.": "Adicione um emprego primeiro: a indústria trabalha com um.",
 "Remove it": "Remover",
 "Adult video as a career of its own: offers of one title at a time instead of shifts, labels and their sets, performers who are only ever on set, sales and a weekly chart, fame, and what the people around the player think of it. Only with adult content on.": "O vídeo adulto como carreira própria: propostas de um título por vez em vez de turnos, selos e seus sets, artistas que só existem no set, vendas e um ranking semanal, fama e o que as pessoas em volta do jogador pensam disso. Só com conteúdo adulto ligado.",
 "The kinds of title: the skill their scenes lean on, their pay, their scenes in order, and the words checked against a performer's limits.": "Os tipos de título: a habilidade em que as cenas se apoiam, o pagamento, as cenas em ordem e as palavras conferidas com os limites de cada artista.",
 "Who makes the titles: a tier, a rate, the genres they make, their own set and director. A higher tier only offers to a higher rank.": "Quem faz os títulos: um nível, uma taxa, os gêneros que faz, seu próprio set e diretor. Um nível mais alto só faz propostas a um cargo mais alto.",
 "Where titles are shot: a place, or a home (a studio of the player's), the genres it suits, a fee and the risk of being caught.": "Onde os títulos são filmados: um lugar, ou um imóvel (um estúdio do jogador), os gêneros a que serve, uma taxa e o risco de ser flagrado.",
 "Performers who only work in the industry: their cards are made the first time they are on a set, and they are never among the world's people (no routine, no home, never in Messages).": "Artistas que só trabalham na indústria: seus cards são criados na primeira vez que estão num set, e nunca fazem parte das pessoas do mundo (sem rotina, sem casa, nunca em Mensagens).",
 "Drawn pictures of a performer's scenes: a scene with them and a matching genre or words shows one, the least shown first. The player is never in one.": "Imagens desenhadas das cenas de um artista: uma cena com ele e um gênero ou palavras que combinem mostra uma, a menos vista primeiro. O jogador nunca aparece nelas.",
