 "Bookings instead of shifts": "Propostas em vez de turnos",
 "From the first rank: offers of one title each in the Take app, no shifts. A title pays the rank's pay × the shift's hours and counts as a shift toward promotion; a rank's days a week are offers a week. Only on the industry's own job.": "Desde o primeiro cargo: propostas de um título cada no app Take, sem turnos. Um título paga o salário do cargo × as horas do turno e conta como um turno para a promoção; os dias por semana de um cargo viram propostas por semana. Só no emprego da própria indústria.",
 "On this track: offers of one title each in the Take app, no shifts. A title pays the rank's pay × the shift's hours and counts as a shift toward promotion; a rank's days a week are offers a week.": "Nesta modalidade: propostas de um título cada no app Take, sem turnos. Um título paga o salário do cargo × as horas do turno e conta como um turno para a promoção; os dias por semana de um cargo viram propostas por semana.",
