 "Word is going round that {0} cuts corners: contracts nobody reads, a performer who wasn't told what the scene was.": "Corre o boato de que {0} faz tudo nas coxas: contratos que ninguém lê, um artista que não soube qual era a cena.",
 "The police raid {0}'s set over a contract: it's shut for a week, and nothing is made there until it reopens.": "A polícia faz uma batida no set de {0} por causa de um contrato: fica fechado por uma semana, e nada é feito ali até reabrir.",
 "The police raid your label's set over a contract: it's shut for a week, and nothing is made there until it reopens.": "A polícia faz uma batida no set do seu selo por causa de um contrato: fica fechado por uma semana, e nada é feito ali até reabrir.",
 "A tabloid prints {0}'s real name beside one of {1}'s titles. Her family reads it; she leaves the label: {2}.": "Um tabloide publica o nome verdadeiro de {0} ao lado de um dos títulos de {1}. A família dela lê; ela deixa o selo: {2}.",
 "A tabloid prints {0}'s real name beside one of {1}'s titles. Her family reads it; she leaves the label.": "Um tabloide publica o nome verdadeiro de {0} ao lado de um dos títulos de {1}. A família dela lê; ela deixa o selo.",
 "A tabloid prints {0}'s real name beside one of your label's titles. Her family reads it; she leaves the label: {1}.": "Um tabloide publica o nome verdadeiro de {0} ao lado de um dos títulos do seu selo. A família dela lê; ela deixa o selo: {1}.",
 "A tabloid prints {0}'s real name beside one of your label's titles. Her family reads it; she leaves the label.": "Um tabloide publica o nome verdadeiro de {0} ao lado de um dos títulos do seu selo. A família dela lê; ela deixa o selo.",
 "Scandal: {0}": "Escândalo: {0}",
