 "Performers and the set": "Artistas e o set",
 "A label's brief can name a performer and what she wears; her agency sends her to the shoot's place for its window, with no plan to set. A label's brief shot on one of its sets books you onto a shoot day instead: be on set and take the stills between scenes, and the best becomes the title's cover.": "A pauta de um selo pode trazer o nome de uma artista e o que ela veste; a agência dela a manda ao local da sessão no horário certo, sem plano a marcar. Já a pauta de um selo fotografada num dos seus sets te escala para um dia de filmagem: esteja no set e faça as fotos de cena entre as cenas, e a melhor vira a capa do título.",
 "A performer who has made her name may get a photobook of her own, offered once {0} knows your work.": "Uma artista que já fez nome pode ganhar um fotolivro próprio, oferecido quando {0} conhecer o seu trabalho.",
 "A director with a camera can take the stills between scenes, from Things to do on set, and so can a photographer a label books for them. The best still becomes the title's cover and sells its first week up to a tenth more by its stars; a title's page in Take shows its stills.": "Quem dirige e tem uma câmera pode fazer as fotos de cena entre as cenas, em O que fazer no set, e também um fotógrafo que o selo escala para isso. A melhor foto de cena vira a capa do título e faz a primeira semana vender até um décimo a mais, conforme as estrelas; a página do título no Take mostra as fotos de cena.",
 "Your own photobook": "Seu próprio fotolivro",
